descriptor.templateCss:
* { box-sizing: border-box; }
.cc-widget {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
    max-height: 100%;
    font-family: 'Roboto', sans-serif;
    background: #ffffff;
    padding: 8px 10px;
    overflow: hidden;
}
.cc-title-row {
    flex: 0 0 auto;
    min-height: 0;
    padding-bottom: 4px;
}
.cc-title {
    font-family: 'Roboto', sans-serif;
    font-size: 15px;
    font-weight: 500;
    line-height: 20px;
    color: rgba(0, 0, 0, 0.87);
}
/* ---- Aviso "cambios de signo sin guardar" + boton "Guardar cambios",
   mismo patron que el widget de dias anteriores (cd.css / .cd-aviso-guardar) ---- */
.cc-aviso-guardar {
    display: none;
    flex: 0 0 auto;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    background: #fff8e1;
    border: 1px solid #ffca28;
    border-radius: 4px;
    padding: 6px 10px;
    margin-bottom: 6px;
    font-family: 'Roboto', sans-serif;
    font-size: 12px;
    color: rgba(0, 0, 0, 0.76);
}
.cc-btn-guardar {
    flex: 0 0 auto;
    font-family: 'Roboto', sans-serif;
    font-size: 12px;
    font-weight: 700;
    border: none;
    border-radius: 4px;
    padding: 6px 14px;
    cursor: pointer;
    background: #2e7d32;
    color: #ffffff;
}
.cc-btn-guardar:hover { background: #256428; }
.cc-btn-guardar:disabled { opacity: 0.6; cursor: default; }

.cc-legend-panel {
    flex: 0 0 auto;
    min-height: 0;
    max-height: 130px;
    overflow-y: auto;
    overflow-x: auto;
    padding-bottom: 2px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.12);
    margin-bottom: 4px;
}
.cc-legend-header {
    display: flex;
    align-items: baseline;
    gap: 10px;
    font-size: 10px;
    line-height: 1.2;
    color: rgba(0, 0, 0, 0.54);
    padding-bottom: 3px;
    width: fit-content;
}
.cc-legend-header-spacer { flex: 0 0 8px; }
.cc-legend-header-name { flex: 0 0 170px; }
.cc-legend-header-col { flex: 0 0 82px; text-align: right; white-space: nowrap; padding-right: 10px; }
/* Columnas "Caudal actual", "Volumen total", Ayer (-1) y Antes de ayer (-2):
   en negrita y con más tamaño que el resto de cabeceras, para que destaquen
   de un vistazo frente a "Combinar" y el resto de la leyenda. */
.cc-legend-header-destacado { font-weight: 700; font-size: 12px; color: rgba(0, 0, 0, 0.72); }
.cc-legend-row {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 1px 0;
    width: fit-content;
    cursor: default;
}
.cc-legend-row.cc-legend-clickable { cursor: pointer; }
.cc-legend-row.cc-legend-off { opacity: 0.35; }
.cc-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    flex: 0 0 8px;
}
/* Punto de leyenda para la serie "Caudal Medio": trazo discontinuo en vez
   de circulo solido -- ahora que comparte color con "Caudal instantáneo"
   para el dia de hoy, esto es lo que las distingue en la leyenda. */
.cc-dot-discontinuo {
    width: 10px;
    height: 0;
    border-radius: 0;
    border-top: 2px dashed currentColor;
    background: none;
    flex: 0 0 10px;
}
.cc-legend-name {
    flex: 0 0 170px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-family: 'Roboto', sans-serif;
    font-size: 12px;
    font-weight: 400;
    line-height: 16px;
    color: rgba(0, 0, 0, 0.76);
}
.cc-legend-val {
    flex: 0 0 82px;
    text-align: right;
    padding-right: 10px;
    font-variant-numeric: tabular-nums;
    font-family: 'Roboto', sans-serif;
    font-size: 12px;
    font-weight: 500;
    line-height: 16px;
    color: rgba(0, 0, 0, 0.76);
}
.cc-legend-val-clickable {
    cursor: pointer;
    border-radius: 3px;
    padding: 1px 3px;
    margin: -1px -3px;
}
.cc-legend-val-clickable:hover {
    background: rgba(0, 0, 0, 0.06);
}
.cc-legend-val-activo {
    color: #1976d2;
    font-weight: 700;
    background: rgba(25, 118, 210, 0.1);
}
.cc-legend-val-activo:hover {
    background: rgba(25, 118, 210, 0.16);
}
.cc-legend-val-disabled {
    cursor: default;
    opacity: 0.4;
}
.cc-legend-val-disabled:hover {
    background: transparent;
}
.cc-legend-daymark {
    display: inline-block;
    width: 14px;
    height: 0;
    margin-right: 4px;
    vertical-align: middle;
    border-top-width: 2px;
    border-top-style: solid;
    border-top-color: currentColor;
}
/* El discontinuo (rayas / puntos) se reserva SOLO para "Caudal medio" (una
   media/agregado, no una lectura directa) -- así en el propio icono de la
   leyenda ya se ve qué líneas serán discontinuas en la gráfica y cuáles no. */
.cc-legend-daymark-media-1 { border-top-style: dashed; }
.cc-legend-daymark-media-2 { border-top-style: dashed; }
/* El resto de filas (lecturas: caudalímetros, Caudal Guarda, Caudal Manual)
   se superponen como línea CONTINUA -- se distinguen de la línea de "hoy"
   por el color (variarColor en el JS), no por el trazo. */
.cc-legend-daymark-solid { border-top-style: solid; }
.cc-chart-panel {
    flex: 1 1 auto;
    min-height: 0;
    position: relative;
    min-width: 0;
    /* Fix: dejamos hueco a la derecha para que la etiqueta del último punto
       (p.ej. "5 L/s" en la línea de Caudal medio) no quede cortada por el
       overflow:hidden del widget cuando el punto cae pegado al borde. */
    padding-right: 42px;
}
#cc-svg {
    display: block;
    overflow: visible;
}
.cc-tooltip {
    position: absolute;
    display: none;
    pointer-events: none;
    background: rgba(255,255,255,0.96);
    border: 1px solid rgba(0,0,0,0.12);
    border-radius: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    padding: 6px 10px;
    font-size: 12px;
    color: rgba(0,0,0,0.76);
    white-space: nowrap;
    z-index: 20;
}
.cc-tooltip-row { display: flex; align-items: center; gap: 6px; }
.cc-tooltip-dot { width: 7px; height: 7px; border-radius: 50%; flex: 0 0 7px; }
.cc-tooltip-time { font-weight: 500; margin-bottom: 3px; color: rgba(0,0,0,0.87); }
.cc-overlay-editar {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000000;
}
.cc-modal-editar {
    background: #ffffff;
    border-radius: 8px;
    padding: 22px 24px 18px;
    width: 320px;
    max-width: 90vw;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
    font-family: 'Roboto', sans-serif;
}
.cc-modal-titulo {
    font-size: 17px;
    font-weight: 700;
    color: rgba(0, 0, 0, 0.87);
    margin-bottom: 2px;
}
.cc-modal-sub {
    font-size: 13px;
    color: rgba(0, 0, 0, 0.54);
    margin-bottom: 10px;
}
.cc-modal-actual {
    font-size: 13px;
    color: rgba(0, 0, 0, 0.7);
    margin-bottom: 10px;
}
.cc-modal-label {
    display: block;
    font-size: 12px;
    font-weight: 600;
    color: rgba(0, 0, 0, 0.6);
    margin-bottom: 4px;
}
.cc-modal-select {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid rgba(0, 0, 0, 0.28);
    border-radius: 4px;
    padding: 7px 8px;
    font-family: inherit;
    font-size: 13px;
    color: rgba(0, 0, 0, 0.87);
    margin-bottom: 10px;
    background: #ffffff;
}
.cc-modal-nota {
    font-size: 12px;
    color: rgba(0, 0, 0, 0.6);
    margin-top: 8px;
    min-height: 16px;
}
.cc-modal-input {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid rgba(0, 0, 0, 0.28);
    border-radius: 4px;
    padding: 8px 10px;
    font-family: inherit;
    font-size: 14px;
    color: rgba(0, 0, 0, 0.87);
    outline: none;
    transition: border-color 0.15s ease;
}
.cc-modal-input:focus { border-color: #1976d2; }
.cc-modal-botones {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 16px;
}
.cc-modal-btn {
    padding: 8px 18px;
    border-radius: 4px;
    border: none;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    font-family: inherit;
}
.cc-modal-btn-cancelar { background: #eceff1; color: #37474f; }
.cc-modal-btn-cancelar:hover { background: #dfe4e8; }
.cc-modal-btn-guardar { background: #1976d2; color: #ffffff; }
.cc-modal-btn-guardar:hover { background: #1662ab; }
.cc-modal-btn-guardar:disabled { opacity: 0.6; cursor: default; }
/* ============================================================
   NUEVO: selector +Suma/-Resta por caudalímetro, integrado en la propia
   leyenda (antes era el widget aparte "Caudalímetros del grupo"). Mismos
   colores que aquel widget (azul = suma, rojo = resta) para que se
   reconozca como la misma acción.
   ============================================================ */
.cc-legend-header-signo { flex-basis: 150px; }
.cc-legend-val-suma { color: #0d47a1; }
.cc-legend-val-resta { color: #b71c1c; }
.cc-legend-signo {
    flex: 0 0 150px;
    display: flex;
    border: 1px solid #607d8b;
    border-radius: 4px;
    overflow: hidden;
    cursor: default;
}
.cc-legend-signo-vacio {
    border: none;
}
.cc-legend-signo-guardando { opacity: 0.55; }
.cc-signo-btn {
    border: none;
    background: #ffffff;
    color: #455a64;
    font-size: 11px;
    font-weight: 700;
    padding: 3px 8px;
    cursor: pointer;
    font-family: inherit;
    flex: 1 1 auto;
    white-space: nowrap;
}
.cc-signo-btn + .cc-signo-btn { border-left: 1px solid #607d8b; }
.cc-signo-btn:hover { background: #eceff1; }
.cc-signo-btn-suma.cc-signo-activo { background: #0d47a1; color: #ffffff; }
.cc-signo-btn-resta.cc-signo-activo { background: #b71c1c; color: #ffffff; }

descriptor.controllerScript:
// ============================================================
// REGISTRO DE CAMBIOS (lo lee el widget de Auditoría)
// Cada vez que este widget cambia un valor, guarda en la entidad una
// telemetría "registro_cambio" con quién lo cambió, el valor ANTERIOR y el
// NUEVO. La Auditoría lee solo esta clave, así que no le afectan los
// recálculos internos (volumen, media proyectada, reescritura del día...).
// ============================================================
var CLAVE_REGISTRO_CAMBIO = 'registro_cambio';
var ultimoTsRegistro = 0;
function usuarioActual(ctx) {
    var u = (ctx && ctx.currentUser) || {};
    if (u.sub || u.email) return u.sub || u.email;
    try {
        var jwt = localStorage.getItem('jwt_token');
        if (jwt) {
            var b64 = jwt.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
            var datos = JSON.parse(decodeURIComponent(escape(atob(b64))));
            return datos.sub || datos.email || '';
        }
    } catch (e) {}
    return '';
}
// cambios: [{ tipo: 'punto'|'media', clave, ts, anterior, nuevo }]
// Los que no cambian de verdad (anterior === nuevo) se descartan solos.
function registrarCambio(ctx, entityType, entityId, cambios) {
    var reales = (cambios || []).map(function (c) {
        var copia = {};
        for (var k in c) { if (c.hasOwnProperty(k)) copia[k] = c[k]; }
        copia.anterior = (c.anterior === null || c.anterior === undefined || isNaN(parseFloat(c.anterior))) ? null : parseFloat(c.anterior);
        copia.nuevo = parseFloat(c.nuevo);
        return copia;
    }).filter(function (c) {
        return !isNaN(c.nuevo) && c.anterior !== c.nuevo;
    });
    if (!reales.length || !entityId) return;
    var ts = Date.now();
    if (ts <= ultimoTsRegistro) ts = ultimoTsRegistro + 1;   // dos registros seguidos no se pisan
    ultimoTsRegistro = ts;
    var payload = { ts: ts, values: {} };
    payload.values[CLAVE_REGISTRO_CAMBIO] = JSON.stringify({ usuario: usuarioActual(ctx), cambios: reales });
    try {
        ctx.http.post('/api/plugins/telemetry/' + (entityType || 'ASSET') + '/' + entityId + '/timeseries/ANY', payload)
            .subscribe(function () {}, function (err) {
                console.error('[registro_cambio] no se pudo guardar el registro del cambio', err);
            });
    } catch (e) {
        console.error('[registro_cambio] excepción al guardar el registro del cambio', e);
    }
}

// ============================================================
// Colores y etiquetas EXACTOS del widget nativo "Comparativa caudales"
//
// Tabla de referencia (la que han pedido que se cumpla):
//   Variable              | Día actual (D)                     | Día anterior (D-1) / Antes de ayer (D-2)
//   Caudal medio          | Media proyectada                   | Suma de caudalímetros
//   Caudal guarda         | su propio valor                    | su propio valor (cierre del día)
//   Caudal manual         | su propio valor                    | su propio valor (cierre del día)
//   Caudal instantáneo    | Suma de todos los caudalímetros    | (vacío)
//   Caudalímetros X       | su propio valor                    | su propio valor (cierre del día)
//
// NUEVO (esta version): las columnas "Ayer" y "Antes de ayer" ya no son solo
// un numero de referencia -- se puede hacer clic en cada una para SUPERPONER
// esa linea completa del dia (no solo el valor de cierre) sobre la grafica
// de hoy, igual que ya se podia ocultar/mostrar la linea de hoy haciendo
// clic en el nombre de la fila. Cada celda Ayer/AntesDeAyer se activa y
// desactiva de forma independiente por fila -- puedes tener, por ejemplo,
// "Caudal medio" de hoy + "Caudal medio" de ayer + un caudalimetro de antes
// de ayer, todos a la vez.
//
// NUEVO (paleta y estilos de línea):
//  - "Caudal medio" y "Caudal instantáneo" tenían colores demasiado
//    parecidos (verde claro / cian, ambos muy luminosos) -- se han
//    sustituido por un verde oscuro y un azul bien diferenciado en tono
//    Y en luminosidad.
//  - "Caudal medio" (sea de hoy o superpuesto de un día anterior) se dibuja
//    SIEMPRE con línea discontinua, y lleva una etiqueta numérica (entero)
//    a la derecha del último punto, encima de la línea. El discontinuo
//    queda reservado en exclusiva para esta serie (es una media/agregado,
//    no una lectura directa).
//  - Las líneas superpuestas de "Ayer" / "Antes de ayer" de una LECTURA
//    (caudalímetro individual, Caudal Guarda, Caudal Manual) se dibujan
//    continuas (igual que la de hoy), pero con un color distinto por día
//    (más oscuro para ayer, más claro para antes de ayer) para que no se
//    confundan con la línea de hoy de esa misma serie.
//
// NUEVO (columnas de días anteriores): las cabeceras "Ayer" / "Antes de
// ayer" se sustituyen por "-1 (DD/MM)" y "-2 (DD/MM)" con la fecha real de
// esos dos días, calculada en cada carga del widget (ver
// actualizarCabecerasDiasAnteriores). Y la línea discontinua del "Caudal
// medio" superpuesto de Antes de ayer usa el MISMO trazo que las otras dos
// (hoy y ayer), en vez de un punteado más fino -- ver DASH_CAUDAL_MEDIO.
// ============================================================
var SERIES_FIJAS = {
    // "Caudal medio" y "Caudal instantáneo" de HOY comparten el MISMO color
    // (azul) -- lo que las distingue ya no es el color sino el trazo
    // (discontinuo solo para "Caudal medio", ver esSerieMedia). Las
    // superposiciones de "Caudal medio" de Ayer/Antes de ayer usan, en vez
    // de este azul, los colores fijos de COLOR_POR_DIA_ANTERIOR (rojo/verde).
    'media_proyectada':  { label: 'Caudal medio',        color: '#0288D1' },
    'caudal_Sum':        { label: 'Caudal instantáneo',  color: '#0288D1' },
    'caudal_manual':     { label: 'Caudal Manual',       color: '#F49836' },
    'caudal_guarda':     { label: 'Caudal Guarda',       color: '#9c27b0' }
};
// Colores fijos por día para la línea "Caudal medio" cuando se superpone un
// día anterior: ayer en rojo, antes de ayer en verde (pedido explícito:
// "el caudal actual y la media de hoy azul / ayer rojo / d-2 verde"). Esto
// sustituye, SOLO para esta serie, al aclarado/oscurecido automático que
// siguen usando el resto de líneas (variarColorPorDia).
var COLOR_POR_DIA_ANTERIOR = { 1: '#E53935', 2: '#2E7D32' };
// Trazo discontinuo de "Caudal medio" -- el MISMO para hoy, ayer y antes de
// ayer (antes, "antes de ayer" usaba un punteado distinto '2,4' que se veía
// diferente al de las otras dos líneas; ahora las tres usan este trazo).
var DASH_CAUDAL_MEDIO = '7,5';
// Orden en el que deben salir las filas fijas en la leyenda (los
// caudalímetros individuales van siempre detrás, en el orden en que
// lleguen). Coincide con el orden de la tabla de referencia.
var ORDEN_FILAS_FIJAS = ['media_proyectada', 'caudal_guarda', 'caudal_manual', 'caudal_Sum'];
// Series visibles al arrancar el widget: el resto (Caudal Manual, Caudal
// Guarda y cada caudalímetro individual) empieza OCULTO, como si se
// hubiera hecho clic en su nombre en la leyenda -- el usuario los puede
// volver a mostrar haciendo clic, igual que siempre.
var SERIES_VISIBLES_POR_DEFECTO = { 'caudal_Sum': true, 'media_proyectada': true };
var COLOR_ENTIDAD_DEFECTO = '#f44336';
var CLAVE_ENTIDAD = 'caudal';
var CLAVE_VOLUMEN = 'caudal_total_diario_m3';
// Clave con la que se lee la media diaria cerrada de CADA caudalímetro
// individual, para sus columnas Ayer / Antes de ayer.
var CLAVE_MEDIA_DIA_ENTIDAD = 'caudal_medio_diario';
// Cada punto de caudal_manual representa un intervalo de 15 minutos (900
// segundos): L/s * 900 s = litros de ESE intervalo, /1000 = m³. Se usa para
// calcular a mano el "Volumen total" de Caudal Manual (no existe esa
// telemetría) y también al corregir un caudalímetro (ver más abajo).
var INTERVALO_MINUTOS = 15;
var FACTOR_VOLUMEN_INTERVALO = INTERVALO_MINUTOS * 60 / 1000; // = 0.9 con 15 min
// Peso temporal (en ms) que se asume para UNA lectura puntual al corregir un
// pico -- mismo intervalo de 15 min que usa el resto del sistema (ver
// FACTOR_VOLUMEN_INTERVALO). Se usa para ajustar "cf_state.sumaPonderada"
// (la media ponderada por tiempo de "caudal_fijado") de forma proporcional,
// sin tener que conocer el hueco real que tuvo esa lectura en su momento.
var PESO_MS_LECTURA = INTERVALO_MINUTOS * 60 * 1000; // = 900000 ms
// Explicaciones de cada serie, para el tooltip nativo del navegador al
// pasar el raton por el nombre en la leyenda -- pedido explicito de
// "los nombres de los titulos deben ser mas explicativos".
var EXPLICACIONES = {
    'media_proyectada':      'Caudal medio: combina el caudal real acumulado del día con la tendencia de las últimas lecturas, extendida hasta el cierre del día. Es una ESTIMACIÓN, no una lectura directa. Ayer/Antes de ayer: suma del valor cerrado de cada caudalímetro ese día. Se dibuja siempre con línea discontinua y su valor actual en una etiqueta junto al final de la línea.',
    'caudal_Sum':             'Caudal instantáneo total: suma en tiempo real del caudal de los caudalímetros medidos ahora mismo (no es una media). No tiene valor de días anteriores.',
    'caudal_manual':          'Caudal introducido a mano cuando no hay lectura automática fiable.',
    'caudal_guarda':          'Caudal reportado por el guarda de la zona.'
};
var EXPLICACION_ENTIDAD = 'Caudal instantáneo medido por este caudalímetro en concreto.';
var EXPLICACION_VOLUMEN = 'Volumen acumulado hasta ahora en el día (m³).';
var EXPLICACION_AYER = 'Valor de ayer. En "Caudal medio" es la suma del valor cerrado de cada caudalímetro ese día; en el resto de filas (Caudal Guarda, Caudal Manual, cada caudalímetro) es su propio valor de cierre del día (23:59h). "Caudal instantáneo" no tiene valor de ayer. Haz clic en el número para superponer la línea completa de ese día en la gráfica.';
var EXPLICACION_ANTESDEAYER = 'Valor de antes de ayer. En "Caudal medio" es la suma del valor cerrado de cada caudalímetro ese día; en el resto de filas (Caudal Guarda, Caudal Manual, cada caudalímetro) es su propio valor de cierre del día (23:59h). "Caudal instantáneo" no tiene valor de antes de ayer. Haz clic en el número para superponer la línea completa de ese día en la gráfica.';
var SVG_NS = 'http://www.w3.org/2000/svg';
var MARGEN = { top: 8, right: 16, bottom: 26, left: 44 };
var ultimoDataset = null; // se guarda para poder redibujar en onResize
var ultimasFilasLeyenda = []; // filas "en vivo", tal y como salen de procesarData
function idDeDatasource(ds) {
    if (!ds) return null;
    return ds.entityId || (ds.entity && ds.entity.id && ds.entity.id.id) || ds.name || null;
}
function tipoDeDatasource(ds) {
    if (!ds) return 'ASSET';
    return ds.entityType || (ds.entity && ds.entity.id && ds.entity.id.entityType) || 'ASSET';
}
// ============================================================
// "Caudal medio" es la única serie tratada como MEDIA/agregado: se dibuja
// siempre discontinua (tanto hoy como en cualquier día superpuesto) y con
// su etiqueta numérica junto al final de la línea. Todo lo demás son
// lecturas directas y se dibujan con línea continua.
// ============================================================
function esSerieMedia(id) {
    return id === 'media_proyectada';
}
// Calcula la etiqueta "-N (DD/MM)" para un día N hacia atrás desde hoy
// (offset 1 = ayer, offset 2 = antes de ayer), con la fecha en curso.
function etiquetaDiaAnterior(offsetDiasAtras) {
    var fecha = new Date();
    fecha.setDate(fecha.getDate() - offsetDiasAtras);
    var dd = ('0' + fecha.getDate()).slice(-2);
    var mm = ('0' + (fecha.getMonth() + 1)).slice(-2);
    return '-' + offsetDiasAtras + ' (' + dd + '/' + mm + ')';
}
