// "caudal_guarda"/"caudal_manual". Esa serie NO hay que recombinarla: la
// cadena de reglas ya la calculó, en su momento, con el signo que estaba
// vigente ESE día -- así que es la fuente correcta y no requiere adivinar
// ningún signo histórico.
// ============================================================

// Color BASE con el que se dibuja una fila -- el mismo que su línea "de
// hoy" (fija en SERIES_FIJAS, o el color por defecto de caudalímetro para
// las filas individuales). Ya NO se usa para las líneas superpuestas de
// Ayer/Antes de ayer (esas usan el color fijo COLOR_POR_DIA_ANTERIOR), se
// deja por si hiciera falta en el futuro.
function colorDeSerie(id, datasets) {
    if (SERIES_FIJAS.hasOwnProperty(id)) { return SERIES_FIJAS[id].color; }
    var encontrado = null;
    (datasets || []).forEach(function(d) { if (d.id === id) { encontrado = d.color; } });
    return encontrado || COLOR_ENTIDAD_DEFECTO;
}
// Activa/desactiva la superposición de una fila+día. Si hace falta,
// dispara la carga (y muestra "…" en la celda mientras tanto); si ya
// estaba en caché, redibuja al instante sin volver a pedir nada.
function alternarOverlay($ctx, id, offset) {
    var key = claveOverlay(id, offset);
    if (overlaysActivos[key]) {
        delete overlaysActivos[key];
        if (ultimoDataset) { dibujarGrafico($ctx, ultimoDataset); }
        pintarLeyenda($ctx, ultimasFilasLeyenda);
        return;
    }
    overlaysActivos[key] = true;
    if (overlaysCache[key] && overlaysCache[key].estado === 'listo') {
        if (ultimoDataset) { dibujarGrafico($ctx, ultimoDataset); }
        pintarLeyenda($ctx, ultimasFilasLeyenda);
        return;
    }
    overlaysCache[key] = { estado: 'cargando', puntos: [] };
    pintarLeyenda($ctx, ultimasFilasLeyenda); // repinta ya para mostrar "…" mientras carga
    function alTerminar(puntos, rango) {
        overlaysCache[key] = { estado: 'listo', puntos: puntos, rango: rango };
        if (ultimoDataset) { dibujarGrafico($ctx, ultimoDataset); }
        pintarLeyenda($ctx, ultimasFilasLeyenda);
    }
    if (id === 'media_proyectada') {
        if (!entityIdBaseGlobal) { alTerminar([], calcularRangoDia(offset)); return; }
        pedirSerieCompletaDelDia($ctx, entityIdBaseGlobal, entityTypeBaseGlobal, 'caudal_Sum', offset, alTerminar);
    } else if (id === 'caudal_guarda' || id === 'caudal_manual') {
        if (!entityIdBaseGlobal) { alTerminar([], calcularRangoDia(offset)); return; }
        pedirSerieCompletaDelDia($ctx, entityIdBaseGlobal, entityTypeBaseGlobal, id, offset, alTerminar);
    } else {
        // Caudalímetro individual: id es su entityId.
        var entType = 'DEVICE';
        entidadesCaudalimetrosGlobal.forEach(function(e) { if (e.entityId === id) { entType = e.entityType; } });
        pedirSerieCompletaDelDia($ctx, id, entType, CLAVE_ENTIDAD, offset, alTerminar);
    }
}
self.onDataUpdated = function() {
    var $ctx = self.ctx;
    ctxGlobal = $ctx;
    actualizarCabecerasDiasAnteriores($ctx);
    var data = $ctx.data || [];
    var resultado = procesarData($ctx, data);
    ultimoDataset = resultado.datasets;
    ultimasFilasLeyenda = resultado.filasLeyenda;
    if (resultado.entityIdBase) {
        entityIdBaseGlobal = resultado.entityIdBase;
        entityTypeBaseGlobal = resultado.entityTypeBase || 'ASSET';
        if (resultado.entityNombreBase) { entityNombreBaseGlobal = resultado.entityNombreBase; }
    }
    // Se mantiene siempre actualizada (no solo la primera vez) -- la usan
    // los botones +Suma/-Resta de la leyenda y la carga de días anteriores
    // de cada caudalímetro individual.
    entidadesCaudalimetrosGlobal = resultado.entidadesCaudalimetros;
    if (!datosDiasAnterioresCargados && resultado.entityIdBase) {
        datosDiasAnterioresCargados = true; // se marca ya para no lanzar la peticion mas de una vez
        var entidades = [
            { id: resultado.entityIdBase, entityType: resultado.entityTypeBase, clave: 'caudal_guarda' },
            { id: resultado.entityIdBase, entityType: resultado.entityTypeBase, clave: 'caudal_manual' },
            // "caudal_fijado" del Grupo_Riego -- el mismo valor único que se
            // ve en el Calendario para ese día (una recta, no una media que
            // varía con la hora). Es lo que se dibuja como línea "Caudal
            // medio" al superponer Ayer/Antes de ayer (ver dibujarGrafico).
            { id: resultado.entityIdBase, entityType: resultado.entityTypeBase, clave: 'caudal_fijado' }
        ];
        resultado.entidadesCaudalimetros.forEach(function(ent) {
            entidades.push({ id: ent.entityId, entityType: ent.entityType, clave: CLAVE_MEDIA_DIA_ENTIDAD });
        });
        cargarDatosDiasAnteriores($ctx, entidades);
    }
    if (!signosPeticionLanzada && resultado.entityIdBase) {
        signosPeticionLanzada = true; // se marca ya para no lanzar la peticion mas de una vez
        cargarSignosCaudalimetros($ctx);
    }
    pintarLeyenda($ctx, resultado.filasLeyenda);
    // Se espera a que el navegador termine de acomodar la leyenda (puede
    // cambiar de alto si hay muchos caudalímetros) ANTES de medir el hueco
    // que le queda a la gráfica -- si se mide en el mismo instante, a veces
    // coge un tamaño desactualizado y deja hueco vacío sin usar debajo.
    requestAnimationFrame(function() {
        dibujarGrafico($ctx, resultado.datasets);
    });
};
// Construye datasets + filasLeyenda a partir de un array "data" tal y como
// llega de la suscripcion en vivo. No pinta nada -- solo calcula.
function procesarData($ctx, data) {
    var datasets = [];
    var filasLeyenda = [];
    // ---- PASO 1: averiguar la entidad BASE (STATE) antes de nada ----
    // Se necesita saber esto primero porque caudal_total_diario_m3 existe
    // con el MISMO nombre tanto en la entidad base como en cada
    // caudalímetro -- sin saber cuál es cuál de antemano, se mezclaban.
    var entityIdBase = null;
    var entityTypeBase = 'ASSET';
    var entityNombreBase = null;
    data.forEach(function(item) {
        var keyName = item.dataKey && item.dataKey.name;
        if (entityIdBase) return;
        if (SERIES_FIJAS.hasOwnProperty(keyName)) {
            entityIdBase = idDeDatasource(item.datasource);
            entityTypeBase = tipoDeDatasource(item.datasource);
            entityNombreBase = (item.datasource && (item.datasource.entityLabel || item.datasource.entityName)) || null;
        }
    });
    // ---- PASO 2: las series fijas + su volumen total (SOLO de la entidad base) ----
    // caudal_total_diario_m3 no se dibuja como linea -- solo se lee su
    // ultimo valor, y unicamente si pertenece de verdad a la entidad base
    // (no a un caudalímetro que comparta el mismo nombre de clave). El
    // volumen total acumulado se cuelga de "caudal_Sum".
    var volumenTotalBase = null;
    var volumenTotalBaseTs = null;
    var idClaveVolumenBase = 'caudal_Sum';
    data.forEach(function(item) {
        var keyName = item.dataKey && item.dataKey.name;
        var esDeLaBase = idDeDatasource(item.datasource) === entityIdBase;
        if (keyName === CLAVE_VOLUMEN && esDeLaBase) {
            var puntosVol = (item.data || []).map(function(p) { return { x: p[0], y: p[1] }; });
            var ultVol = puntosVol.length > 0 ? puntosVol[puntosVol.length - 1] : null;
            if (ultVol) {
                volumenTotalBase = parseFloat(ultVol.y);
                volumenTotalBaseTs = ultVol.x;
            }
            return;
        }
        if (!SERIES_FIJAS.hasOwnProperty(keyName) || !esDeLaBase) return;
        asegurarEstadoPorDefecto(keyName);
        var def = SERIES_FIJAS[keyName];
        var puntos = (item.data || []).map(function(p) { return { x: p[0], y: parseFloat(p[1]) }; });
        datasets.push({ id: keyName, label: def.label, color: def.color, puntos: puntos, entityId: entityIdBase, entityType: entityTypeBase, telemetryKey: keyName });
        var ultimo = puntos.length > 0 ? puntos[puntos.length - 1].y : null;
        // "Caudal Manual" no tiene ninguna clave de volumen en la telemetría
        // (no existe ese dato) -- se calcula aquí mismo, sumando cada punto
        // manual con la misma conversión de 15 min (x0.9) que ya usamos para
        // el ajuste de volumen al corregir un caudalímetro.
        var volumenManual = null;
        if (keyName === 'caudal_manual' && puntos.length > 0) {
            var sumaM3 = 0;
            puntos.forEach(function(p) { if (!isNaN(p.y)) { sumaM3 += p.y * FACTOR_VOLUMEN_INTERVALO; } });
            volumenManual = Math.round(sumaM3 * 100) / 100;
        }
        filasLeyenda.push({ id: keyName, color: def.color, nombre: def.label, caudalActual: ultimo, volumenTotal: volumenManual });
    });
    // Solo la fila "principal" (caudal_Sum) lleva el volumen total
    // acumulado -- se rellena aquí porque el orden de "data" no está
    // garantizado. También se guarda el valor+ts DENTRO del propio dataset,
    // para poder ajustarlo si se corrige un caudalimetro.
    if (volumenTotalBase !== null) {
        filasLeyenda.forEach(function(f) { if (f.id === idClaveVolumenBase) { f.volumenTotal = volumenTotalBase; } });
        datasets.forEach(function(ds) {
            if (ds.id === idClaveVolumenBase) { ds.volumen = volumenTotalBase; ds.volumenTs = volumenTotalBaseTs; ds.volumenTelemetryKey = CLAVE_VOLUMEN; }
        });
    }
    // ---- PASO 3: series por entidad (caudalímetros) -- EXCLUYENDO la entidad base ----
    var porEntidad = {};
    data.forEach(function(item) {
        var keyName = item.dataKey && item.dataKey.name;
        if (keyName !== CLAVE_ENTIDAD && keyName !== CLAVE_VOLUMEN) return;
        var entityId = idDeDatasource(item.datasource);
        if (!entityId || entityId === entityIdBase) return; // la base no es un "caudalímetro"
        if (!porEntidad[entityId]) {
            porEntidad[entityId] = {
                nombre: item.datasource.entityLabel || item.datasource.entityName || entityId,
                // NOMBRE REAL (crudo) de la entidad, tal cual está en ThingsBoard --
                // distinto de "nombre" de arriba, que puede llevar un label o alias
                // "bonito" configurado en el widget. El widget "Caudalímetros del
                // grupo" (y la cadena de reglas que lee "operaciones_caudalimetros")
                // usa SIEMPRE este nombre real como clave del mapa de signos, así
                // que hay que usar el mismo aquí para leer/guardar el mismo dato.
                entityNameCrudo: item.datasource.entityName || entityId,
                caudalPuntos: null,
                volumenUltimo: null,
                volumenTs: null,
                entityType: 'DEVICE' // los caudalímetros son siempre DEVICE, confirmado
            };
        }
        if (keyName === CLAVE_ENTIDAD) {
            porEntidad[entityId].caudalPuntos = (item.data || []).map(function(p) { return { x: p[0], y: parseFloat(p[1]) }; });
            if (item.dataKey.label && item.dataKey.label !== '${entityLabel}') {
                porEntidad[entityId].nombre = item.dataKey.label;
            }
        } else {
            var vol = (item.data || []).map(function(p) { return { x: p[0], y: p[1] }; });
            var puntoVol = vol.length > 0 ? vol[vol.length - 1] : null;
            if (puntoVol) {
                porEntidad[entityId].volumenUltimo = parseFloat(puntoVol.y);
                porEntidad[entityId].volumenTs = puntoVol.x;
            }
        }
    });
    var entidadesCaudalimetros = [];
    // FIX (2026-10-06): los caudalimetros se pintan SIEMPRE ordenados por
    // toma (CAU-79-1, CAU-79-2, CAU-79-3, CAU-79-4...), con orden
    // "natural" de los numeros, y no en el orden en que llegan los datos.
    var collaCaudalimetros = new Intl.Collator('es', { numeric: true, sensitivity: 'base' });
    function nombreOrden(id) { return (porEntidad[id].nombre || porEntidad[id].entityNameCrudo || id).toString(); }
    Object.keys(porEntidad).sort(function(a, b) {
        var c = collaCaudalimetros.compare(nombreOrden(a), nombreOrden(b));
        return c !== 0 ? c : collaCaudalimetros.compare(a, b);
    }).forEach(function(entityId) {
        var info = porEntidad[entityId];
        asegurarEstadoPorDefecto(entityId);
        var puntos = info.caudalPuntos || [];
        datasets.push({
            id: entityId, label: info.nombre, color: COLOR_ENTIDAD_DEFECTO, puntos: puntos,
            entityId: entityId, entityType: 'DEVICE', telemetryKey: CLAVE_ENTIDAD,
            volumen: info.volumenUltimo, volumenTs: info.volumenTs, volumenTelemetryKey: CLAVE_VOLUMEN
        });
        var ultimo = puntos.length > 0 ? puntos[puntos.length - 1].y : null;
        filasLeyenda.push({ id: entityId, color: COLOR_ENTIDAD_DEFECTO, nombre: info.nombre, nombreReal: info.entityNameCrudo, caudalActual: ultimo, volumenTotal: info.volumenUltimo });
        entidadesCaudalimetros.push({ entityId: entityId, entityType: info.entityType, nombreReal: info.entityNameCrudo });
    });
    // ---- PASO 4: orden de las filas -- las fijas en el orden de la tabla
    // de referencia (Caudal medio, Caudal Guarda, Caudal Manual, Caudal
    // instantáneo), y los caudalímetros individuales detrás, ordenados por
    // toma (CAU-79-1, CAU-79-2, CAU-79-3...).
    filasLeyenda.sort(function(a, b) {
        var ia = ORDEN_FILAS_FIJAS.indexOf(a.id);
        var ib = ORDEN_FILAS_FIJAS.indexOf(b.id);
        if (ia === -1) ia = ORDEN_FILAS_FIJAS.length;
        if (ib === -1) ib = ORDEN_FILAS_FIJAS.length;
        if (ia !== ib) return ia - ib;
        if (ia === ORDEN_FILAS_FIJAS.length) {
            return collaCaudalimetros.compare((a.nombre || a.nombreReal || a.id).toString(), (b.nombre || b.nombreReal || b.id).toString());
        }
        return 0;
    });
    return { datasets: datasets, filasLeyenda: conDiasAnteriores(filasLeyenda), entityIdBase: entityIdBase, entityTypeBase: entityTypeBase, entityNombreBase: entityNombreBase, entidadesCaudalimetros: entidadesCaudalimetros };
}
function fmt(n) {
    if (n === null || n === undefined || isNaN(n)) return '-';
    var redondeado = Math.round(n);
    var negativo = redondeado < 0;
    var texto = Math.abs(redondeado).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    return (negativo ? '-' : '') + texto;
}
// ============================================================
// FIX (2026-10-06): AJUSTES DE VOLUMEN POR CORRECCIÓN DE PICOS
// El "Volumen total" del grupo se calcula sumando los volúmenes de sus
// caudalímetros (para que cuadre con las filas de abajo). Al corregir un
// pico de "Caudal instantáneo" no se toca ningún caudalímetro, así que esa
// suma no cambiaría -- por eso cada corrección guarda en el Grupo_Riego,
// en la clave "ajuste_volumen_correccion_m3" y con el ts del punto
// corregido, cuántos m³ cambia el volumen del día. El total del grupo es
// la suma de los caudalímetros MÁS todos los ajustes del día. Se guarda
// como telemetría (no en el volumen del grupo), porque la cadena de reglas
// reescribe el volumen del grupo con cada trama y se perdería.
// Lo usan los dos widgets (día actual y días anteriores).
// ============================================================
var CLAVE_AJUSTE_VOLUMEN = 'ajuste_volumen_correccion_m3';
var ajustesVolumenHoy = {};            // ts -> m3 (ajuste acumulado de ese punto)
var ajustesVolumenClaveCargada = null; // "entityId|inicioDia" de lo cargado
var ajustesVolumenCargando = false;
function claveAjustesHoy() {
    if (!entityIdBaseGlobal) return null;
    return entityIdBaseGlobal + '|' + calcularInicioFinDiaLocal(Date.now()).inicio;
}
function sumaAjustesVolumenHoy() {
    var t = 0;
    for (var k in ajustesVolumenHoy) { if (ajustesVolumenHoy.hasOwnProperty(k)) { var v = parseFloat(ajustesVolumenHoy[k]); if (!isNaN(v)) t += v; } }
    return t;
}
function cargarAjustesVolumenHoy($ctx, callback) {
    var clave = claveAjustesHoy();
    if (!clave || ajustesVolumenCargando) return;
    ajustesVolumenCargando = true;
    var dia = calcularInicioFinDiaLocal(Date.now());
    var url = '/api/plugins/telemetry/' + entityTypeBaseGlobal + '/' + entityIdBaseGlobal + '/values/timeseries?keys=' + CLAVE_AJUSTE_VOLUMEN + '&startTs=' + dia.inicio + '&endTs=' + dia.fin + '&limit=10000';
    $ctx.http.get(url).subscribe(function(data) {
        var mapa = {};
        ((data && data[CLAVE_AJUSTE_VOLUMEN]) || []).forEach(function(p) { mapa[p.ts] = parseFloat(p.value) || 0; });
        ajustesVolumenHoy = mapa;
        ajustesVolumenClaveCargada = clave;
        ajustesVolumenCargando = false;
        if (callback) callback();
    }, function() {
        ajustesVolumenHoy = {};
        ajustesVolumenClaveCargada = clave;
        ajustesVolumenCargando = false;
        if (callback) callback();
    });
}
function pintarLeyenda($ctx, filas) {
    // Si todavía no se han leído los ajustes de volumen de hoy (o ha
    // cambiado el grupo o el día), se leen y se vuelve a pintar.
    if (entityIdBaseGlobal && ajustesVolumenClaveCargada !== claveAjustesHoy() && !ajustesVolumenCargando) {
