            if (!ent) { return; }
            var v = parseFloat(f.volumenTotal);
            if (f.volumenTotal === null || f.volumenTotal === undefined || isNaN(v)) { return; }
            var nombreSigno = f.nombreReal || ent.nombreReal || f.nombre;
            var signo = (signosOriginalesGlobal[nombreSigno] === 'resta') ? -1 : 1;
            suma += signo * v;
