        });
    })();
    var $lista = $ctx.$container.find('#cc-legend-list').empty();
    filasConDias.forEach(function(f) {
        var explicacion = EXPLICACIONES.hasOwnProperty(f.id) ? EXPLICACIONES[f.id] : EXPLICACION_ENTIDAD;
        var tituloAttr = (f.nombre + ' — ' + explicacion).replace(/"/g, '&quot;');
        var tituloVolumen = (f.nombre + ' — ' + EXPLICACION_VOLUMEN).replace(/"/g, '&quot;');
        var tituloAyer = (f.nombre + ' — ' + EXPLICACION_AYER).replace(/"/g, '&quot;');
        var tituloAntesDeAyer = (f.nombre + ' — ' + EXPLICACION_ANTESDEAYER).replace(/"/g, '&quot;');
        var oculto = !!seriesOcultas[f.id];
        // --- Celdas Ayer / Antes de ayer: clicables si la fila tiene dato
        // de ese día (todas menos "Caudal instantáneo"). Muestran "…"
        // mientras se está cargando la línea completa de ese día, y quedan
        // resaltadas en azul mientras esa línea está superpuesta.
        var claveAyer = claveOverlay(f.id, 1);
        var claveAntesDeAyer = claveOverlay(f.id, 2);
        var puedeAyer = (f.ayer !== null && f.ayer !== undefined);
        var puedeAntesDeAyer = (f.antesDeAyer !== null && f.antesDeAyer !== undefined);
        var activoAyer = !!overlaysActivos[claveAyer];
        var activoAntesDeAyer = !!overlaysActivos[claveAntesDeAyer];
        var cargandoAyer = overlaysCache[claveAyer] && overlaysCache[claveAyer].estado === 'cargando';
        var cargandoAntesDeAyer = overlaysCache[claveAntesDeAyer] && overlaysCache[claveAntesDeAyer].estado === 'cargando';
        var textoAyer = cargandoAyer ? '…' : (puedeAyer ? fmt(f.ayer) + ' L/s' : '-');
        var textoAntesDeAyer = cargandoAntesDeAyer ? '…' : (puedeAntesDeAyer ? fmt(f.antesDeAyer) + ' L/s' : '-');
        // El icono de la leyenda (daymark) refleja el MISMO estilo y color
        // con el que se dibujará esa línea si se activa: discontinuo (y
