        // superpuestas, no solo "Caudal medio": esos dias no tienen "Caudal
        // instantaneo" con el que puedan confundirse, asi que ya no hace
        // falta aclarar/oscurecer el color propio de cada lectura -- se usa
        // directamente el color fijo del dia.
        var colorAyer = COLOR_POR_DIA_ANTERIOR[1];
        var colorAntesDeAyer = COLOR_POR_DIA_ANTERIOR[2];
        var claseDaymarkAyer = esMedia ? 'cc-legend-daymark-media-1' : 'cc-legend-daymark-solid';
        var claseDaymarkAntesDeAyer = esMedia ? 'cc-legend-daymark-media-2' : 'cc-legend-daymark-solid';
        var marcaAyer = puedeAyer ? '<span class="cc-legend-daymark ' + claseDaymarkAyer + '" style="color:' + colorAyer + '"></span>' : '';
        var marcaAntesDeAyer = puedeAntesDeAyer ? '<span class="cc-legend-daymark ' + claseDaymarkAntesDeAyer + '" style="color:' + colorAntesDeAyer + '"></span>' : '';
        var claseAyer = 'cc-legend-val' + (puedeAyer ? ' cc-legend-val-clickable' : ' cc-legend-val-disabled') + (activoAyer ? ' cc-legend-val-activo' : '');
        var claseAntesDeAyer = 'cc-legend-val' + (puedeAntesDeAyer ? ' cc-legend-val-clickable' : ' cc-legend-val-disabled') + (activoAntesDeAyer ? ' cc-legend-val-activo' : '');
        // El punto de la leyenda de "Caudal medio" se dibuja como un trazo
        // discontinuo (en vez de un circulo solido) -- ahora que comparte
        // el mismo azul que "Caudal instantáneo" para el día de hoy, esto
        // es lo único que los distingue de un vistazo en la leyenda.
        var claseDot = esMedia ? 'cc-dot cc-dot-discontinuo' : 'cc-dot';
        // --- NUEVO: selector +Suma/-Resta, solo en la fila de cada
        // caudalímetro individual, y solo si hay más de uno (con uno solo
        // no hay nada que combinar -- igual que en el widget aparte del
        // que viene esto). El valor "Caudal actual" de esa fila se colorea
        // también según el signo elegido, para verlo de un vistazo.
        var esCaudalimetroIndividual = entidadesCaudalimetrosGlobal.some(function(e) { return e.entityId === f.id; });
        // El selector +Suma/-Resta solo aparece si, ADEMÁS de haber más de
        // un caudalímetro, el grupo (entidad base) es uno de los 3
        // autorizados (ver GRUPOS_CON_SIGNO) -- en el resto de grupos esta
        // opción no debe poder tocarse, aunque tengan varios caudalímetros.
        var mostrarSelectorSigno = esCaudalimetroIndividual && entidadesCaudalimetrosGlobal.length > 1 && grupoPermiteSigno(entityNombreBaseGlobal);
        var signoActual = signosCaudalimetros[f.nombreReal || f.nombre] === 'resta' ? 'resta' : 'suma';
        var claseValCaudal = esCaudalimetroIndividual ? (signoActual === 'resta' ? ' cc-legend-val-resta' : ' cc-legend-val-suma') : '';
        var htmlSigno;
        if (mostrarSelectorSigno) {
            htmlSigno =
                '<span class="cc-legend-signo' + (guardandoSignosGlobal ? ' cc-legend-signo-guardando' : '') + '" data-signo-entity="' + f.id + '">' +
                    '<button type="button" class="cc-signo-btn cc-signo-btn-suma' + (signoActual !== 'resta' ? ' cc-signo-activo' : '') + '" data-signo="suma" title="Sumar este caudalímetro al caudal del grupo, a partir de su próxima lectura">+ Suma</button>' +
                    '<button type="button" class="cc-signo-btn cc-signo-btn-resta' + (signoActual === 'resta' ? ' cc-signo-activo' : '') + '" data-signo="resta" title="Restar este caudalímetro del caudal del grupo, a partir de su próxima lectura">− Resta</button>' +
                '</span>';
        } else {
            htmlSigno = '<span class="cc-legend-signo cc-legend-signo-vacio"></span>';
        }
        var $row = $(
            '<div class="cc-legend-row cc-legend-clickable' + (oculto ? ' cc-legend-off' : '') + '" data-serie-id="' + f.id + '" title="Clic para ' + (oculto ? 'mostrar' : 'ocultar') + ' esta línea">' +
                '<span class="' + claseDot + '" style="background:' + (esMedia ? 'none' : f.color) + ';color:' + f.color + '"></span>' +
                '<span class="cc-legend-name" title="' + tituloAttr + '">' + f.nombre + '</span>' +
                '<span class="cc-legend-val' + claseValCaudal + '" title="' + tituloAttr + '">' + fmt(f.caudalActual) + ' L/s</span>' +
                '<span class="cc-legend-val" title="' + tituloVolumen + '">' + (f.volumenTotal !== null ? fmt(f.volumenTotal) + ' m³' : '') + '</span>' +
                '<span class="' + claseAyer + '" data-overlay-id="' + f.id + '" data-overlay-offset="1" title="' + tituloAyer + '">' + marcaAyer + textoAyer + '</span>' +
                '<span class="' + claseAntesDeAyer + '" data-overlay-id="' + f.id + '" data-overlay-offset="2" title="' + tituloAntesDeAyer + '">' + marcaAntesDeAyer + textoAntesDeAyer + '</span>' +
                htmlSigno +
            '</div>'
        );
        $lista.append($row);
    });
    // Clic en el NOMBRE/fila entera -> oculta/muestra la línea de HOY (igual que antes).
    $lista.find('.cc-legend-row').off('click').on('click', function(evt) {
        // Si el clic ha sido en una celda de Ayer/Antes de ayer o en el
        // selector +Suma/-Resta, cada uno ya tiene su propio handler (más
        // abajo) -- no togglear también la fila.
        if ($(evt.target).closest('.cc-legend-val-clickable, .cc-legend-val-disabled, .cc-legend-signo').length > 0) { return; }
        var id = $(this).attr('data-serie-id');
        if (seriesOcultas[id]) { delete seriesOcultas[id]; } else { seriesOcultas[id] = true; }
        $(this).toggleClass('cc-legend-off', !!seriesOcultas[id]);
        if (ultimoDataset) { dibujarGrafico($ctx, ultimoDataset); }
    });
    // Clic en una celda Ayer/Antes de ayer -> superpone/quita esa línea del día.
    $lista.find('.cc-legend-val-clickable').off('click').on('click', function(evt) {
        evt.stopPropagation();
        var id = $(this).attr('data-overlay-id');
        var offset = parseInt($(this).attr('data-overlay-offset'));
        alternarOverlay($ctx, id, offset);
    });
    // Clic en +Suma / -Resta -> cambia el signo SOLO en pantalla (vista
    // previa, en memoria). No se llama al servidor todavia -- eso lo hace
    // el boton "Guardar cambios" del aviso (ver pintarAvisoGuardarSigno /
    // guardarCambiosDeSignoHoy), igual que en el widget de dias anteriores.
    $lista.find('.cc-signo-btn').off('click').on('click', function(evt) {
        evt.stopPropagation();
        if (guardandoSignosGlobal) { return; }
        var $btn = $(this);
        if ($btn.hasClass('cc-signo-activo')) { return; }
        var $cont = $btn.closest('.cc-legend-signo');
        var entityId = $cont.attr('data-signo-entity');
        var nuevoSigno = $btn.attr('data-signo');
        var fila = ultimasFilasLeyenda.find(function(f) { return f.id === entityId; });
        if (!fila) return;
        var nombre = fila.nombreReal || fila.nombre;
        var signoAnterior = signosCaudalimetros[nombre] === 'resta' ? 'resta' : 'suma';
        if (signoAnterior === nuevoSigno) return;
        signosCaudalimetros[nombre] = nuevoSigno;
        pintarLeyenda($ctx, ultimasFilasLeyenda);
    });
    pintarAvisoGuardarSigno($ctx);
}

// Aviso de "cambios de signo sin guardar" + boton "Guardar cambios", justo
// encima de la leyenda -- mismo patron que cd.js (widget de dias
// anteriores). Se crea una sola vez y despues solo se muestra/oculta, para
// no perder el foco del boton mientras se esta guardando.
function pintarAvisoGuardarSigno($ctx) {
    var $panelLeyenda = $ctx.$container.find('.cc-legend-panel');
    var $aviso = $ctx.$container.find('#cc-aviso-guardar-signo');
    if ($aviso.length === 0) {
        $aviso = $('<div id="cc-aviso-guardar-signo" class="cc-aviso-guardar">' +
            '<span class="cc-aviso-texto">Hay cambios de Suma/Resta sin guardar.</span>' +
            '<button type="button" class="cc-btn-guardar">Guardar cambios</button>' +
        '</div>');
        $panelLeyenda.before($aviso);
        $aviso.find('.cc-btn-guardar').on('click', function() { guardarCambiosDeSignoHoy($ctx); });
    }
    $aviso.toggle(hayCambiosSignoSinGuardar() && !guardandoSignosGlobal);
}

// Guardado real -- se ejecuta al pulsar "Guardar cambios". Escribe de una
// vez el mapa completo de signos en el Grupo_Riego (mismo atributo que ya
// lee la cadena de reglas); no toca ninguna telemetria, el cambio se aplica
// prospectivamente a partir de la proxima lectura de cada caudalimetro.
function guardarCambiosDeSignoHoy($ctx) {
    if (guardandoSignosGlobal) { return; }
    if (!hayCambiosSignoSinGuardar()) { return; }
    guardandoSignosGlobal = true;
    var $btn = $ctx.$container.find('.cc-btn-guardar').prop('disabled', true).text('Guardando...');
    pintarLeyenda($ctx, ultimasFilasLeyenda);
    var copiaSignos = {};
    for (var k in signosCaudalimetros) { if (signosCaudalimetros.hasOwnProperty(k)) { copiaSignos[k] = signosCaudalimetros[k]; } }
    guardarSignosCaudalimetros($ctx, copiaSignos, function() {
        signosOriginalesGlobal = JSON.parse(JSON.stringify(copiaSignos));
        guardandoSignosGlobal = false;
        $btn.prop('disabled', false).text('Guardar cambios');
        pintarLeyenda($ctx, ultimasFilasLeyenda);
    }, function() {
        guardandoSignosGlobal = false;
        $btn.prop('disabled', false).text('Guardar cambios');
        pintarLeyenda($ctx, ultimasFilasLeyenda);
        alert('No se pudieron guardar los cambios de Suma/Resta. Vuelve a intentarlo.');
    });
}
// ============================================================
// Grafico SVG a mano: eje X fijo con las 24 horas del dia de hoy
// (00:00 a 24:00), eje Y en base al min/max de los datos.
// ============================================================
// Dibuja, junto al último punto de una línea de "Caudal medio", una
// etiqueta con su valor entero -- a la derecha del punto y ligeramente
// por encima de la línea, como se ha pedido. Se usa tanto para la línea
// de hoy como para cualquier superposición de Ayer/Antes de ayer de esa
// misma fila (la única serie tratada como "media", ver esSerieMedia).
function dibujarEtiquetaCaudalMedio(svg, crearEl, puntos, color) {
    if (!puntos || puntos.length === 0) return;
    var ultimo = puntos[puntos.length - 1];
    var texto = crearEl('text', {
        x: ultimo.xPix + 6, y: ultimo.yPix - 6,
        'font-size': 11, 'font-family': 'Roboto, sans-serif',
        'font-weight': 700, fill: color, 'text-anchor': 'start'
    });
    texto.textContent = fmt(ultimo.y) + ' L/s';
    svg.appendChild(texto);
}
// Dibuja una pequeña marca vertical ("guioncito") en cada punto donde ha
// habido una lectura real, permanente (no solo al pasar el ratón) -- así
// se ve de un vistazo dónde hay dato real y dónde la línea solo interpola
// entre dos lecturas. El círculo más grande que aparece al pasar el ratón
// por encima (ver hoverGroup) sigue funcionando igual, por encima de esto.
function dibujarMarcasDePunto(svg, crearEl, puntosPix, color, opacidad) {
    if (!puntosPix) return;
    puntosPix.forEach(function(p) {
        svg.appendChild(crearEl('line', {
            x1: p.xPix, y1: p.yPix - 3, x2: p.xPix, y2: p.yPix + 3,
            stroke: color, 'stroke-width': 1.5,
            opacity: opacidad !== undefined ? opacidad : 1
        }));
    });
}
function dibujarGrafico($ctx, datasets) {
    var $panel = $ctx.$container.find('.cc-chart-panel');
    var svg = $ctx.$container.find('#cc-svg')[0];
    if (!svg) return;
    var ancho = $panel.width();
    var alto = $panel.height();
    if (ancho <= 0 || alto <= 0) return;
    while (svg.firstChild) { svg.removeChild(svg.firstChild); }
    svg.setAttribute('viewBox', '0 0 ' + ancho + ' ' + alto);
    var anchoPlot = ancho - MARGEN.left - MARGEN.right;
    var altoPlot = alto - MARGEN.top - MARGEN.bottom;
    if (anchoPlot <= 0 || altoPlot <= 0) return;
    // Series ocultadas por el usuario (clic en la leyenda, o el estado por
    // defecto de arranque): no cuentan para la escala, no se dibujan, no
    // aparecen en el punto/tooltip al pasar el ratón.
    var datasetsVisibles = datasets.filter(function(ds) { return !seriesOcultas[ds.id]; });
    // --- Dominio X: siempre el dia de hoy ---
    var tsReferencia = null;
    datasetsVisibles.forEach(function(ds) {
        ds.puntos.forEach(function(p) {
            if (!isNaN(p.y) && (tsReferencia === null || p.x > tsReferencia)) { tsReferencia = p.x; }
        });
    });
    var fechaRef = tsReferencia !== null ? new Date(tsReferencia) : new Date();
    var inicioDia = new Date(fechaRef.getFullYear(), fechaRef.getMonth(), fechaRef.getDate(), 0, 0, 0).getTime();
    var finDia = inicioDia + 24 * 60 * 60 * 1000;
    // --- Overlays activos: remapear cada uno a la misma franja 00:00-24:00
    // de HOY (aunque sus puntos originales sean de ayer/antes de ayer),
    // desplazando por la diferencia entre el inicio de SU día y el de hoy.
    // Así una línea de ayer y la de hoy quedan alineadas por HORA DEL DÍA,
    // que es lo que hace falta para poder compararlas visualmente.
    //
    // Estilo: "Caudal medio" (esSerieMedia) se dibuja SIEMPRE discontinua
    // (con el MISMO trazo -- DASH_CAUDAL_MEDIO -- para hoy, ayer y antes de
    // ayer, para que las tres se reconozcan de un vistazo como la misma
    // magnitud) y mantiene su color base. Cualquier otra fila (lectura
    // directa) se dibuja CONTINUA, con un color derivado del base (más
    // oscuro para ayer, más claro para antes de ayer) para no confundirse
    // con la línea de hoy de esa misma fila.
    var capasOverlay = [];
    Object.keys(overlaysActivos).forEach(function(key) {
        var cache = overlaysCache[key];
        if (!cache || cache.estado !== 'listo' || cache.puntos.length === 0) return;
        var separador = key.lastIndexOf('::');
        var id = key.slice(0, separador);
        var offset = parseInt(key.slice(separador + 2));
        var esMedia = esSerieMedia(id);
        // Todas las líneas superpuestas (Caudal medio, Caudal Guarda, Caudal
        // Manual, cada caudalímetro) usan el color FIJO del día -- rojo para
        // ayer, verde para antes de ayer -- en vez del aclarado/oscurecido
        // automático de antes: esos días no tienen "Caudal instantáneo" con
        // el que puedan confundirse, así que no hace falta distinguirlas
        // también por tono.
        var color = COLOR_POR_DIA_ANTERIOR[offset];
        var puntosRemapeados = cache.puntos.map(function(p) {
            return { x: inicioDia + (p.x - cache.rango.inicio), y: p.y };
        }).filter(function(p) { return p.x >= inicioDia && p.x < finDia && !isNaN(p.y); });
        if (puntosRemapeados.length === 0) return;
        var etiquetaBase = SERIES_FIJAS.hasOwnProperty(id) ? SERIES_FIJAS[id].label : (function() {
            var enc = null;
            datasets.forEach(function(d) { if (d.id === id) { enc = d.label; } });
            return enc || id;
        })();
        var sufijoDia = offset === 1 ? ' (Ayer)' : ' (Antes de ayer)';
        if (esMedia) {
            // "Caudal medio" de un día anterior: lo que se pide (la propia
            // serie histórica "caudal_Sum" del Grupo_Riego, ver
            // alternarOverlay) es la suma INSTANTÁNEA de ese día, no una
            // media. Antes solo se dibujaba esa línea instantánea pero con
            // el estilo de "media" (discontinua + etiqueta al final) -- se
            // veía el dato equivocado con el estilo equivocado. Ahora se
            // dibujan las DOS, del mismo color: la instantánea (continua, de
            // fondo) y su "Caudal medio" real -- una RECTA horizontal al
            // valor de caudal_fijado de ese día (discontinua, con la
            // etiqueta numérica al final), ver más abajo.
            capasOverlay.push({
                id: id, offset: offset, color: color,
                label: etiquetaBase + ' instantáneo' + sufijoDia,
                puntos: puntosRemapeados,
                dasharray: null,
                esMediaCapa: false
            });
            // El "Caudal medio" de un día ya cerrado NO es una curva que
            // varía con la hora -- es UN ÚNICO valor fijado para todo el
            // día (el mismo "caudal_fijado" que se ve en el Calendario para
            // esa fecha), así que se dibuja como una RECTA horizontal a esa
            // altura, de punta a punta del día. Se lee de
            // valoresAyer/valoresAntesDeAyer, clave "caudal_fijado" de la
            // entidad base -- ya se pide junto con caudal_guarda/caudal_manual
            // en cargarDatosDiasAnteriores. El trazo es SIEMPRE
            // DASH_CAUDAL_MEDIO, igual que la línea de hoy -- ya no hay un
            // punteado distinto para "antes de ayer".
            var claveFijado = claveDia(entityIdBaseGlobal, 'caudal_fijado');
            var valorFijado = (offset === 1) ? valoresAyer[claveFijado] : valoresAntesDeAyer[claveFijado];
            if (valorFijado !== null && valorFijado !== undefined) {
                capasOverlay.push({
                    id: id, offset: offset, color: color,
                    label: etiquetaBase + ' medio' + sufijoDia,
                    puntos: [{ x: inicioDia, y: valorFijado }, { x: finDia - 1, y: valorFijado }],
                    dasharray: DASH_CAUDAL_MEDIO,
                    esMediaCapa: true
                });
            }
        } else {
            capasOverlay.push({
                id: id, offset: offset, color: color,
                label: etiquetaBase + sufijoDia,
                puntos: puntosRemapeados,
                dasharray: null,
                esMediaCapa: false
            });
        }
    });
    // --- Dominio Y: min/max de todos los puntos con dato (hoy + overlays activos) ---
    var yMin = Infinity, yMax = -Infinity;
    datasetsVisibles.forEach(function(ds) {
        ds.puntos.forEach(function(p) {
            if (p.x < inicioDia || p.x >= finDia) return;
            if (isNaN(p.y)) return;
            if (p.y < yMin) yMin = p.y;
            if (p.y > yMax) yMax = p.y;
        });
    });
    capasOverlay.forEach(function(capa) {
        capa.puntos.forEach(function(p) {
            if (p.y < yMin) yMin = p.y;
            if (p.y > yMax) yMax = p.y;
        });
    });
    if (yMin === Infinity) { yMin = 0; yMax = 100; }
    if (yMin === yMax) { yMin -= 1; yMax += 1; }
    // El eje Y siempre arranca en 0 -- no en el minimo real de los datos.
    var escala = calcularEscalaRedonda(0, yMax, 5);
    yMin = 0;
    yMax = escala.max;
    function xPix(ts) { return MARGEN.left + ((ts - inicioDia) / (finDia - inicioDia)) * anchoPlot; }
    function yPix(v) { return MARGEN.top + (1 - (v - yMin) / (yMax - yMin)) * altoPlot; }
    function crearEl(tag, attrs) {
        var el = document.createElementNS(SVG_NS, tag);
        for (var k in attrs) { el.setAttribute(k, attrs[k]); }
        return el;
    }
    // --- Lineas de rejilla verticales, UNA POR HORA (24 marcas fijas) ---
    for (var h = 0; h <= 24; h++) {
        var ts = inicioDia + h * 60 * 60 * 1000;
        var x = xPix(ts);
        svg.appendChild(crearEl('line', {
            x1: x, y1: MARGEN.top, x2: x, y2: MARGEN.top + altoPlot,
            stroke: 'rgba(0,0,0,0.12)', 'stroke-width': 1
        }));
        if (h < 24) {
            var texto = crearEl('text', {
                x: x, y: MARGEN.top + altoPlot + 14,
                'font-size': 9, 'font-family': 'Roboto, sans-serif',
                fill: 'rgba(0,0,0,0.54)', 'text-anchor': 'middle'
            });
            texto.textContent = (h < 10 ? '0' + h : h) + ':00';
            svg.appendChild(texto);
        }
    }
    // --- Lineas de rejilla horizontales (Y) ---
    // Si al redondear varios de los "ticks" acaban mostrando el MISMO
    // numero (rango de datos muy estrecho, tipo 153-154), no repetimos esa
    // etiqueta una y otra vez -- solo se muestra abajo (el minimo) y arriba
    // (el maximo), y ya esta.
    var etiquetasUnicas = {};
    escala.ticks.forEach(function(v) { etiquetasUnicas[fmt(v)] = true; });
    var valoresY = (Object.keys(etiquetasUnicas).length <= 2)
        ? [escala.ticks[0], escala.ticks[escala.ticks.length - 1]]
        : escala.ticks;
    valoresY.forEach(function(valor) {
        var y = yPix(valor);
        svg.appendChild(crearEl('line', {
            x1: MARGEN.left, y1: y, x2: MARGEN.left + anchoPlot, y2: y,
            stroke: 'rgba(0,0,0,0.12)', 'stroke-width': 1
        }));
        var textoY = crearEl('text', {
            x: MARGEN.left - 6, y: y + 3,
            'font-size': 10, 'font-family': 'Roboto, sans-serif',
            fill: 'rgba(0,0,0,0.54)', 'text-anchor': 'end'
        });
        textoY.textContent = fmt(valor);
        svg.appendChild(textoY);
    });
    // --- Eje (bordes) ---
    svg.appendChild(crearEl('line', {
        x1: MARGEN.left, y1: MARGEN.top, x2: MARGEN.left, y2: MARGEN.top + altoPlot,
        stroke: 'rgba(0,0,0,0.54)', 'stroke-width': 1
    }));
    svg.appendChild(crearEl('line', {
        x1: MARGEN.left, y1: MARGEN.top + altoPlot, x2: MARGEN.left + anchoPlot, y2: MARGEN.top + altoPlot,
        stroke: 'rgba(0,0,0,0.54)', 'stroke-width': 1
    }));
    // --- Una polyline por serie en vivo visible (línea continua salvo
    // "Caudal medio", que va discontinua y con etiqueta de su valor) ---
    datasetsVisibles.forEach(function(ds) {
        var puntosValidos = ds.puntos.filter(function(p) { return p.x >= inicioDia && p.x < finDia && !isNaN(p.y); });
        if (puntosValidos.length === 0) return;
        var esMedia = esSerieMedia(ds.id);
        var coords = puntosValidos.map(function(p) { return xPix(p.x) + ',' + yPix(p.y); }).join(' ');
        var attrsLinea = { points: coords, fill: 'none', stroke: ds.color, 'stroke-width': 2 };
        if (esMedia) { attrsLinea['stroke-dasharray'] = DASH_CAUDAL_MEDIO; }
        svg.appendChild(crearEl('polyline', attrsLinea));
        var puntosConPixeles = puntosValidos.map(function(p) { return { y: p.y, xPix: xPix(p.x), yPix: yPix(p.y) }; });
        dibujarMarcasDePunto(svg, crearEl, puntosConPixeles, ds.color);
        if (esMedia) {
            dibujarEtiquetaCaudalMedio(svg, crearEl, puntosConPixeles, ds.color);
        }
    });
    // --- Una polyline por cada Ayer/Antes de ayer activado ---
    capasOverlay.forEach(function(capa) {
        var coords = capa.puntos.map(function(p) { return xPix(p.x) + ',' + yPix(p.y); }).join(' ');
        var attrsLinea = { points: coords, fill: 'none', stroke: capa.color, 'stroke-width': 2, opacity: 0.9 };
        if (capa.dasharray) { attrsLinea['stroke-dasharray'] = capa.dasharray; }
        svg.appendChild(crearEl('polyline', attrsLinea));
        var puntosConPixelesOv = capa.puntos.map(function(p) { return { y: p.y, xPix: xPix(p.x), yPix: yPix(p.y) }; });
        dibujarMarcasDePunto(svg, crearEl, puntosConPixelesOv, capa.color, 0.9);
        // La etiqueta con el valor al final de la línea es SOLO de la capa
        // de media (discontinua) -- la instantánea (continua) no lleva
        // etiqueta, igual que "Caudal instantáneo" de hoy tampoco la lleva.
        if (capa.esMediaCapa) {
            dibujarEtiquetaCaudalMedio(svg, crearEl, puntosConPixelesOv, capa.color);
        }
    });
    // --- Capa transparente para tooltip + click (edicion de un caudalimetro) ---
    var $tooltip = $ctx.$container.find('#cc-tooltip');
    var overlay = crearEl('rect', {
        x: MARGEN.left, y: MARGEN.top, width: anchoPlot, height: altoPlot,
        fill: 'transparent'
    });
    overlay.style.cursor = 'crosshair';
    svg.appendChild(overlay);
    // Puntitos que aparecen sobre la linea, en el punto exacto, al pasar el raton
    var hoverGroup = crearEl('g', { id: 'cc-hover-dots' });
    svg.appendChild(hoverGroup);
    overlay.addEventListener('mousemove', function(evt) {
        var rectPix = svg.getBoundingClientRect();
        var mx = (evt.clientX - rectPix.left) * (ancho / rectPix.width);
        var ts = inicioDia + ((mx - MARGEN.left) / anchoPlot) * (finDia - inicioDia);
        var filas = [];
        datasetsVisibles.forEach(function(ds) {
            var cercano = null, mejorDist = Infinity;
            ds.puntos.forEach(function(p) {
                var d = Math.abs(p.x - ts);
                if (d < mejorDist) { mejorDist = d; cercano = p; }
            });
            if (cercano && mejorDist < 30 * 60 * 1000) {
                filas.push({ label: ds.label, color: ds.color, value: cercano.y, ts: cercano.x });
            }
        });
        // También se busca el punto más cercano en cada línea superpuesta
        // (Ayer/Antes de ayer), ya remapeada a la franja horaria de hoy.
        capasOverlay.forEach(function(capa) {
            var cercano = null, mejorDist = Infinity;
            capa.puntos.forEach(function(p) {
                var d = Math.abs(p.x - ts);
                if (d < mejorDist) { mejorDist = d; cercano = p; }
            });
            if (cercano && mejorDist < 30 * 60 * 1000) {
                filas.push({ label: capa.label, color: capa.color, value: cercano.y, ts: cercano.x });
            }
        });
        while (hoverGroup.firstChild) { hoverGroup.removeChild(hoverGroup.firstChild); }
        if (filas.length === 0) { $tooltip.hide(); return; }
        filas.forEach(function(f) {
            hoverGroup.appendChild(crearEl('circle', {
                cx: xPix(f.ts), cy: yPix(f.value), r: 4,
                fill: f.color, stroke: '#ffffff', 'stroke-width': 1.5
            }));
        });
        var horaTexto = new Date(filas[0].ts).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
        var html = '<div class="cc-tooltip-time">' + horaTexto + '</div>';
        filas.forEach(function(f) {
            html += '<div class="cc-tooltip-row"><span class="cc-tooltip-dot" style="background:' + f.color + '"></span>' + f.label + ': ' + fmt(f.value) + ' L/s</div>';
        });
        $tooltip.html(html).css({ visibility: 'hidden', display: 'block' });
        // Bocadillo "inteligente": si pegado al cursor se saldria del
        // panel (por la derecha o por abajo), lo volcamos hacia el otro
        // lado en vez de dejar que se corte fuera del widget.
        var anchoTooltip = $tooltip.outerWidth();
        var altoTooltip = $tooltip.outerHeight();
        var left = evt.offsetX + 12;
        var top = evt.offsetY + 12;
        if (left + anchoTooltip > ancho) { left = evt.offsetX - anchoTooltip - 12; }
        if (top + altoTooltip > alto) { top = evt.offsetY - altoTooltip - 12; }
        if (left < 0) { left = 4; }
        if (top < 0) { top = 4; }
        $tooltip.css({ left: left + 'px', top: top + 'px', visibility: 'visible' });
    });
    overlay.addEventListener('mouseleave', function() {
        $tooltip.hide();
        while (hoverGroup.firstChild) { hoverGroup.removeChild(hoverGroup.firstChild); }
    });
    // ============================================================
    // CLIC en la gráfica -> corregir la lectura de "Caudal instantáneo"
    // que está bajo el ratón (la más cercana en el tiempo a donde se pulsa),
    // para limpiar lecturas puntuales disparadas ("picos"). (Antes saltaba
    // siempre al valor más alto del día; ya no.)
    //
    // OJO -- el pico se busca en "Caudal instantáneo" (caudal_Sum, la
    // curva real que se ve dibujada), NO en la lectura bruta de cada
    // caudalímetro por separado. Un pico casi siempre aparece SOLO en la
    // suma combinada (p.ej. un caudalímetro en "-Resta" cuyo descuento se
    // pierde un instante) sin que ningún caudalímetro individual muestre
    // nada raro -- si se buscara el máximo caudalímetro por caudalímetro,
    // se "encontraba" como pico cualquier lectura alta pero normal (caso
    // real: El Marchante marcaba el pico a las 3:00 porque ahí un
    // caudalímetro llegaba a su máximo habitual de ~93 L/s, nada anómalo
    // -- el pico de verdad, a las 7:30, solo se ve en "Caudal instantáneo").
    //
    // La corrección se aplica DIRECTAMENTE sobre el valor de "Caudal
    // instantáneo" del GRUPO de riego -- ya NO se edita ningún
    // caudalímetro individual. El valor del caudalímetro que haya podido
    // originar el pico no importa para este ajuste: lo único que se
    // corrige es el dato del grupo, y de ahí se recalculan bien la media
    // (media_proyectada) y el caudal fijado. Al guardar se actualiza YA el
    // propio dataset en local (ver más abajo, tras "encadenar"), sin
    // esperar a la suscripción.
    //
    // Solo se corrige HOY (las líneas superpuestas de Ayer/Antes de ayer
    // no son editables desde aquí).
    // ============================================================
    var datasetCaudalActual = null;
    datasets.forEach(function(ds) {
        if (ds.id === 'caudal_Sum') { datasetCaudalActual = ds; }
    });
    overlay.addEventListener('click', function(evt) {
        if (!datasetCaudalActual || datasetCaudalActual.puntos.length === 0) return;
        // FIX (2026-10-06): se corrige el punto de "Caudal instantáneo" que
        // está bajo el ratón (el más cercano en el tiempo a donde se ha
        // pulsado), igual que el que enseña el tooltip -- ya NO se salta
        // automáticamente al valor más alto del día.
        var rectPix = svg.getBoundingClientRect();
        var mx = (evt.clientX - rectPix.left) * (ancho / rectPix.width);
        var tsClick = inicioDia + ((mx - MARGEN.left) / anchoPlot) * (finDia - inicioDia);
        var puntoSel = puntoMasCercano(datasetCaudalActual, tsClick, 30 * 60 * 1000);
        if (!puntoSel) return; // no hay ninguna lectura cerca de donde se ha pulsado
        abrirModalEdicion($ctx, puntoSel.x, datasetCaudalActual);
    });
}
// Busca, dentro de un dataset, el punto mas cercano en el tiempo a un ts dado.
function puntoMasCercano(dataset, ts, margenMs) {
    var cercano = null, mejorDist = Infinity;
    dataset.puntos.forEach(function(p) {
        if (isNaN(p.y)) return;
        var d = Math.abs(p.x - ts);
        if (d < mejorDist) { mejorDist = d; cercano = p; }
    });
    if (!cercano || (margenMs !== undefined && mejorDist > margenMs)) return null;
    return cercano;
}
// ============================================================
// NUEVO: sincronizar la corrección de un pico con los ACUMULADORES en vivo
// que alimentan "media_proyectada" y "caudal_fijado" del Grupo_Riego --
// antes, corregir un pico solo reescribía el histórico mostrado
// (caudal/caudal_Sum), pero el acumulador seguía sumando el valor ORIGINAL
// (el que de verdad llegó por la cadena de reglas en su momento), así que
// "media_proyectada"/"caudal_fijado" seguían arrastrando el dato erróneo
// el resto del día. Ahora, al guardar una corrección, se aplica el MISMO
// delta a esos acumuladores, para que la proyección reaccione al instante.
//
//  - media_proyectada: atributos simples "suma"/"contador"/"last_4" del
//    Grupo_Riego (ver "Procesar Ciclo (tz Madrid)" en Pila_de_Datos_v2.3).
//    Es una media simple (no ponderada por tiempo): un punto corregido
//    solo desplaza "suma" en el mismo delta, sin tocar "contador". Se
//    actualiza también el ultimo valor de "last_4" si el punto corregido
//    es el más reciente (para que la tendencia a corto plazo también
//    refleje el cambio, no solo el acumulado del día).
//  - caudal_fijado: atributo "cf_state" (JSON) del Grupo_Riego -- media
//    PONDERADA POR TIEMPO ("Calcular caudal fijado (incremental)"). No se
//    puede desplazar con un delta simple sin saber el hueco temporal real
//    que tuvo ese punto en su momento -- se aproxima con el mismo
//    intervalo de referencia que usa el resto del sistema (15 min, ver
//    PESO_MS_LECTURA), que es razonable porque los caudalímetros reportan
//    a ese ritmo. Si el punto corregido es el ULTIMO conocido (el más
//    reciente respecto a "ultimoTs"), se actualiza tambien "ultimoValor"
//    para que el tramo que queda hasta la proxima lectura ya pondere con
//    el valor corregido, no con el antiguo.
// ============================================================
function leerAtributosServidor($ctx, entityId, entityType, claves, callback) {
    var url = '/api/plugins/telemetry/' + entityType + '/' + entityId + '/values/attributes/SERVER_SCOPE?keys=' + claves.join(',');
    $ctx.http.get(url).subscribe(function(data) {
        var mapa = {};
        (data || []).forEach(function(a) { mapa[a.key] = a.value; });
        callback(mapa);
    }, function(err) {
        console.warn('[Comparativa Caudales] no se pudieron leer atributos', claves, 'de', entityId, err);
        callback({});
    });
}
function guardarAtributosServidor($ctx, entityId, entityType, payload, callback) {
    try {
        $ctx.http.post('/api/plugins/telemetry/' + entityType + '/' + entityId + '/SERVER_SCOPE', payload).subscribe(
            function() { callback(true); },
            function(err) { console.warn('[Comparativa Caudales] no se pudieron guardar atributos', payload, err); callback(false); }
        );
    } catch (e) {
        console.error('[Comparativa Caudales] excepción guardando atributos', e);
        callback(false);
    }
}
// Aplica el delta de una corrección a los acumuladores en vivo del
// Grupo_Riego. "esUltimaLectura" indica si el punto corregido es (o es
// posterior a) la última lectura conocida por el acumulador -- en ese
// caso también se corrige el "arrastre" hacia adelante (last_4/ultimoValor),
// no solo el histórico acumulado. Nunca hace fallar el guardado principal
// de la corrección si algo de esto falla -- solo avisa por consola: el
// dato de caudal_Sum ya se ha corregido bien, esto es un ajuste adicional.
function sincronizarAcumuladoresConCorreccion($ctx, entityId, entityType, tsPunto, delta, callback) {
    console.log('[CC-SYNC] arrancando sincronizacion -- entityId=' + entityId + ' entityType=' + entityType + ' tsPunto=' + tsPunto + ' (' + new Date(tsPunto).toISOString() + ') delta=' + delta);
    if (!delta || isNaN(delta) || delta === 0) { console.log('[CC-SYNC] delta invalido o cero, no se hace nada'); callback(); return; }
    var pendientes = 2;
    var huboError = false;
    function unaTerminada(ok, motivo) {
        console.log('[CC-SYNC] paso terminado -- ok=' + ok + (motivo ? (' motivo=' + motivo) : ''));
        if (!ok) { huboError = true; }
        pendientes--;
        if (pendientes === 0) { console.log('[CC-SYNC] sincronizacion completa -- huboError=' + huboError); callback(huboError); }
    }
    // --- 1) media_proyectada: suma/contador/last_4 (media simple) ---
    leerAtributosServidor($ctx, entityId, entityType, ['suma', 'contador', 'last_4', 'ultimo_ts_contado'], function(attrs) {
        console.log('[CC-SYNC] atributos leidos para media_proyectada:', JSON.stringify(attrs));
        var sumaActual = parseFloat(attrs.suma);
        if (isNaN(sumaActual)) { unaTerminada(true, 'sin atributo "suma" todavia (valor recibido: ' + JSON.stringify(attrs.suma) + ') -- no se ajusta'); return; }
        var nuevaSuma = Math.round((sumaActual + delta) * 1000) / 1000;
        var payload = { suma: nuevaSuma };
        // Si el punto corregido es la lectura MAS RECIENTE que conoce el
        // acumulador (o mas reciente todavia), se actualiza tambien el
        // ultimo valor guardado en "last_4" -- si no, el siguiente ciclo
        // seguiria proyectando con la tendencia antigua un rato mas.
        var ultimoTsContado = parseInt(attrs.ultimo_ts_contado);
        if (!isNaN(ultimoTsContado) && tsPunto >= ultimoTsContado && attrs.last_4) {
            var arr = String(attrs.last_4).split(',').map(Number).filter(function(v) { return !isNaN(v); });
            if (arr.length > 0) {
                arr[arr.length - 1] = Math.round((arr[arr.length - 1] + delta) * 1000) / 1000;
                payload.last_4 = arr.join(',');
            }
        }
        console.log('[CC-SYNC] escribiendo payload media_proyectada:', JSON.stringify(payload), '(suma anterior=' + sumaActual + ')');
        guardarAtributosServidor($ctx, entityId, entityType, payload, function(ok) { unaTerminada(ok, ok ? undefined : 'fallo al POST de suma/last_4'); });
    });
    // --- 2) caudal_fijado: cf_state (media ponderada por tiempo) ---
    leerAtributosServidor($ctx, entityId, entityType, ['cf_state'], function(attrs) {
        console.log('[CC-SYNC] atributo cf_state leido (crudo):', JSON.stringify(attrs.cf_state));
        if (!attrs.cf_state) { unaTerminada(true, 'sin atributo "cf_state" todavia -- no se ajusta'); return; }
        var estado;
        try { estado = JSON.parse(attrs.cf_state); } catch (e) { unaTerminada(true, 'cf_state no es JSON valido: ' + e); return; }
        if (!estado || typeof estado.sumaPonderada !== 'number') { unaTerminada(true, 'cf_state sin campo sumaPonderada numerico: ' + JSON.stringify(estado)); return; }
        var sumaPonderadaAnterior = estado.sumaPonderada;
        estado.sumaPonderada = Math.round((estado.sumaPonderada + delta * PESO_MS_LECTURA) * 1000) / 1000;
        // Si el punto corregido es la ultima lectura conocida por este
        // estado (o mas reciente), se actualiza tambien "ultimoValor" --
        // asi el tramo pendiente hasta la proxima lectura real pondera ya
        // con el valor corregido.
        if (typeof estado.ultimoTs === 'number' && tsPunto >= estado.ultimoTs && typeof estado.ultimoValor === 'number') {
            estado.ultimoValor = Math.round((estado.ultimoValor + delta) * 1000) / 1000;
        }
        console.log('[CC-SYNC] escribiendo cf_state nuevo:', JSON.stringify(estado), '(sumaPonderada anterior=' + sumaPonderadaAnterior + ')');
        guardarAtributosServidor($ctx, entityId, entityType, { cf_state: JSON.stringify(estado) }, function(ok) { unaTerminada(ok, ok ? undefined : 'fallo al POST de cf_state'); });
    });
}
// ============================================================
// NUEVO: forzar YA la reescritura de los puntos de telemetria
// "media_proyectada" y "caudal_fijado" de HOY, con el valor recalculado a
// partir de los acumuladores YA corregidos (ver sincronizarAcumuladoresConCorreccion).
//
// Por que hace falta esto ademas de corregir los atributos: los atributos
// "suma"/"contador"/"last_4"/"cf_state" son solo el ESTADO INTERNO del
// acumulador -- lo que se ve en la grafica son 2 puntos de telemetria fijos
// (00:00 y 23:59:59 de hoy) que solo se recalculan y se vuelven a escribir
// cuando llega la SIGUIENTE trama real y la cadena ejecuta "Generar
// Proyección Futura" / "Calcular caudal fijado (incremental)". Si no llega
// ninguna trama pronto, el grafico se queda enseñando el valor antiguo un
// buen rato aunque el acumulador ya este bien -- confirmado en pruebas
// reales (26/09/2026): tras corregir un pico y sincronizar bien "suma" y
// "cf_state" (logs [CC-SYNC] con ok=true), la grafica seguia en el valor de
// antes hasta que llegara la proxima trama.
//
// Se reproduce aqui, en el navegador, EL MISMO CALCULO que hace
// "Generar Proyección Futura" en la cadena de reglas (Pila_de_Datos_v2.3),
// usando los valores YA corregidos de suma/contador/last_4, y se reescribe
// directamente el punto -- asi la grafica refleja el cambio al instante,
// sin esperar a la proxima lectura del caudalimetro.
// ============================================================
function calcularInicioFinDiaLocal(tsReferencia) {
    var fecha = new Date(tsReferencia);
    var inicio = new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate(), 0, 0, 0, 0).getTime();
    var fin = inicio + 86400000 - 1; // 23:59:59.999
    return { inicio: inicio, fin: fin };
}
function forzarRecalculoInmediato($ctx, entityId, entityType, callback) {
    var ahora = Date.now();
    var dia = calcularInicioFinDiaLocal(ahora);
    var pendientes = 2;
    var huboError = false;
    var valores = { media: null, fijado: null };
    function unaTerminada(ok, motivo) {
        console.log('[CC-FORZAR] paso terminado -- ok=' + ok + (motivo ? (' motivo=' + motivo) : ''));
        if (!ok) { huboError = true; }
        pendientes--;
        if (pendientes === 0) { callback(huboError, valores); }
    }
    // --- media_proyectada: mismo calculo que "Generar Proyección Futura" ---
    leerAtributosServidor($ctx, entityId, entityType, ['suma', 'contador', 'last_4'], function(attrs) {
        var suma = parseFloat(attrs.suma);
        var contador = parseInt(attrs.contador);
        if (isNaN(suma) || isNaN(contador) || contador <= 0) { unaTerminada(true, 'sin suma/contador validos, no se fuerza media_proyectada'); return; }
        var arr = (attrs.last_4 ? String(attrs.last_4).split(',').map(Number).filter(function(v) { return !isNaN(v); }) : []);
        var tendencia = arr.length > 0 ? (arr.reduce(function(a, b) { return a + b; }, 0) / arr.length) : (suma / contador);
        var MS_15_MIN = 900000;
        var slotActual = Math.floor((ahora - dia.inicio) / MS_15_MIN);
        var pasosRestantes = Math.max(0, 96 - (slotActual + 1));
        var sumaSimulada = suma + tendencia * pasosRestantes;
        var contadorSimulado = contador + pasosRestantes;
        var mediaFinal = Math.round((sumaSimulada / contadorSimulado) * 100) / 100;
        valores.media = mediaFinal;
        console.log('[CC-FORZAR] media_proyectada recalculada = ' + mediaFinal + ' (suma=' + suma + ' contador=' + contador + ' tendencia=' + tendencia + ' pasosRestantes=' + pasosRestantes + ')');
        var pendientesPuntos = 2, errorPuntos = false;
        function unPunto(ok) { if (!ok) errorPuntos = true; pendientesPuntos--; if (pendientesPuntos === 0) unaTerminada(!errorPuntos, errorPuntos ? 'fallo al reescribir punto(s) de media_proyectada' : undefined); }
        borrarYGuardarTelemetria($ctx, entityId, entityType, 'media_proyectada', dia.inicio, mediaFinal, unPunto);
        borrarYGuardarTelemetria($ctx, entityId, entityType, 'media_proyectada', dia.fin, mediaFinal, unPunto);
    });
    // --- caudal_fijado: media ponderada por tiempo, a partir de cf_state ya corregido ---
    leerAtributosServidor($ctx, entityId, entityType, ['cf_state'], function(attrs) {
        if (!attrs.cf_state) { unaTerminada(true, 'sin cf_state, no se fuerza caudal_fijado'); return; }
        var estado;
        try { estado = JSON.parse(attrs.cf_state); } catch (e) { unaTerminada(true, 'cf_state no es JSON valido'); return; }
        if (!estado || typeof estado.sumaPonderada !== 'number' || typeof estado.tiempoAcumulado !== 'number' || estado.tiempoAcumulado <= 0) {
            unaTerminada(true, 'cf_state sin sumaPonderada/tiempoAcumulado validos'); return;
        }
        // Se pondera tambien el tramo desde la ultima lectura hasta ahora,
        // igual que hace "Calcular caudal fijado (incremental)" al cerrar el
        // dia -- si no, el valor mostrado ignoraria el hueco desde la
        // ultima lectura real hasta este mismo instante.
        var gapExtra = (typeof estado.ultimoTs === 'number' && typeof estado.ultimoValor === 'number') ? Math.max(0, ahora - estado.ultimoTs) : 0;
        var sumaFinal = estado.sumaPonderada + (estado.ultimoValor || 0) * gapExtra;
        var tiempoFinal = estado.tiempoAcumulado + gapExtra;
        var mediaFinal = tiempoFinal > 0 ? Math.round((sumaFinal / tiempoFinal) * 100) / 100 : 0;
        valores.fijado = mediaFinal;
        console.log('[CC-FORZAR] caudal_fijado recalculado = ' + mediaFinal + ' (sumaPonderada=' + estado.sumaPonderada + ' tiempoAcumulado=' + estado.tiempoAcumulado + ' gapExtra=' + gapExtra + ')');
        var pendientesPuntos = 2, errorPuntos = false;
        function unPunto(ok) { if (!ok) errorPuntos = true; pendientesPuntos--; if (pendientesPuntos === 0) unaTerminada(!errorPuntos, errorPuntos ? 'fallo al reescribir punto(s) de caudal_fijado' : undefined); }
        borrarYGuardarTelemetria($ctx, entityId, entityType, 'caudal_fijado', dia.inicio, mediaFinal, unPunto);
        borrarYGuardarTelemetria($ctx, entityId, entityType, 'caudal_fijado', dia.fin, mediaFinal, unPunto);
    });
}
// ============================================================
// Ventana modal: corregir DIRECTAMENTE el valor de "Caudal instantáneo"
// (caudal_Sum) del Grupo_Riego en el instante del pico detectado. Ya NO
// se edita ningún caudalímetro individual -- el valor del caudalímetro
// que pudiera haber originado el pico es irrelevante para este ajuste: lo
// que de verdad hay que corregir es el dato del grupo, y de ahí se
// recalculan bien la media (media_proyectada) y el caudal fijado, a
// partir del delta (nuevoValor - valorAnterior) del propio grupo.
// ============================================================
function abrirModalEdicion($ctx, tsObjetivo, datasetCaudalSum) {
    $ctx.$container.find('.cc-overlay-editar').remove();
    var fecha = new Date(tsObjetivo);
    var fechaStr = fecha.toLocaleDateString('es-ES') + ' ' + fecha.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
    var $overlay = $(
        '<div class="cc-overlay-editar">' +
            '<div class="cc-modal-editar">' +
                '<div class="cc-modal-titulo">Corregir Caudal instantáneo</div>' +
                '<div class="cc-modal-sub">' + fechaStr + '</div>' +
                '<div class="cc-modal-actual"></div>' +
                '<label class="cc-modal-label">Nuevo valor (L/s)</label>' +
                '<input type="number" class="cc-modal-input" step="any" placeholder="Nuevo valor (L/s)">' +
                '<div class="cc-modal-nota"></div>' +
                '<div class="cc-modal-botones">' +
                    '<button type="button" class="cc-modal-btn cc-modal-btn-cancelar">Cancelar</button>' +
                    '<button type="button" class="cc-modal-btn cc-modal-btn-guardar">Guardar</button>' +
                '</div>' +
            '</div>' +
        '</div>'
    );
    $ctx.$container.append($overlay);
    var $actual = $overlay.find('.cc-modal-actual');
    var $input = $overlay.find('.cc-modal-input');
    var $nota = $overlay.find('.cc-modal-nota');
    // Punto real de "Caudal instantáneo" (caudal_Sum) mas cercano al ts del pico.
    var puntoSum = puntoMasCercano(datasetCaudalSum, tsObjetivo, 30 * 60 * 1000);
    $actual.html(puntoSum
        ? 'Valor actual de Caudal instantáneo: <b>' + fmt(puntoSum.y) + ' L/s</b>'
        : '<span style="color:#d32f2f;">"Caudal instantáneo" no tiene dato en esa hora exacta.</span>');
    $input.trigger('focus');
    function cerrar() { $overlay.remove(); }
    $overlay.find('.cc-modal-btn-cancelar').on('click', cerrar);
    $overlay.on('mousedown', function(evt) { if (evt.target === this) cerrar(); });
    $overlay.find('.cc-modal-btn-guardar').on('click', function() {
        var nuevoValor = parseFloat($input.val());
        if (isNaN(nuevoValor)) { $input.css('border-color', '#d32f2f'); return; }
        if (!puntoSum) { alert('No se puede ajustar: "Caudal instantáneo" no tiene dato cerca de esa hora.'); return; }
        var valorAnteriorSum = puntoSum.y;
        var delta = nuevoValor - valorAnteriorSum;
        var nuevoValorSum = nuevoValor;
        // Misma conversión de intervalo que usa "Caudal Manual" -- ver la
        // constante FACTOR_VOLUMEN_INTERVALO al principio del archivo.
        var deltaVolumenM3 = Math.round(delta * FACTOR_VOLUMEN_INTERVALO * 100) / 100;
        var hayVolBase = datasetCaudalSum.volumen !== null && datasetCaudalSum.volumen !== undefined && datasetCaudalSum.volumenTs !== null;
        var nuevoVolBase = hayVolBase ? Math.round((datasetCaudalSum.volumen + deltaVolumenM3) * 100) / 100 : null;
        $nota.html(
            'Caudal instantáneo: <b>' + fmt(valorAnteriorSum) + '</b> → <b>' + fmt(nuevoValorSum) + '</b> L/s<br>' +
            'Volumen del día: ' + (deltaVolumenM3 >= 0 ? '+' : '') + fmt(deltaVolumenM3) + ' m³<br>' +
            '<i>Se ajustarán también los acumuladores de Caudal medio y Caudal fijado, para que reaccionen al instante.</i>'
        );
        var $btn = $(this).prop('disabled', true).text('Guardando...');
        var borrarYGuardar = function(entityId, entityType, clave, ts, valor, callback) {
            borrarYGuardarTelemetria($ctx, entityId, entityType, clave, ts, valor, callback);
        };
        // Encadena una lista de pasos {entityId, entityType, clave, ts, valor},
        // parando y avisando en el primero que falle -- pero sin deshacer los
        // que ya hayan ido bien (igual que antes: mejor avisar claro que
        // esconder un estado a medias en silencio).
        function encadenar(pasos, avisoSiFalla, callback) {
            var i = 0;
            function siguiente() {
                if (i >= pasos.length) { callback(true); return; }
                var p = pasos[i++];
                borrarYGuardar(p.entityId, p.entityType, p.clave, p.ts, p.valor, function(ok) {
                    if (!ok) { alert(avisoSiFalla(i - 1)); callback(false); return; }
                    siguiente();
                });
            }
            siguiente();
        }
        var pasos = [
            { entityId: datasetCaudalSum.entityId, entityType: datasetCaudalSum.entityType, clave: datasetCaudalSum.telemetryKey, ts: puntoSum.x, valor: nuevoValorSum, nombre: 'Caudal instantáneo' }
        ];
        if (hayVolBase) {
            pasos.push({ entityId: datasetCaudalSum.entityId, entityType: datasetCaudalSum.entityType, clave: datasetCaudalSum.volumenTelemetryKey, ts: datasetCaudalSum.volumenTs, valor: nuevoVolBase, nombre: 'volumen de Caudal instantáneo' });
        }
        encadenar(pasos, function(idxFallo) {
            var nombresOk = pasos.slice(0, idxFallo).map(function(p) { return p.nombre; }).join(', ');
            return 'Se guardó bien: ' + (nombresOk || 'nada') + '. Falló: ' + pasos[idxFallo].nombre + '. Revísalo a mano.';
        }, function(todoOk) {
            if (!todoOk) { $btn.prop('disabled', false).text('Guardar'); return; }
            // Registro para la Auditoría: punto cambiado, valor anterior y nuevo.
            registrarCambio($ctx, datasetCaudalSum.entityType, datasetCaudalSum.entityId, [
                { tipo: 'punto', clave: 'caudal_Sum', ts: puntoSum.x, anterior: valorAnteriorSum, nuevo: nuevoValorSum }
            ]);
            // Ajusta los acumuladores en vivo (media_proyectada / caudal_fijado)
            // con el MISMO delta, calculado DIRECTAMENTE sobre el valor del
            // grupo (nuevoValor - valorAnteriorSum) -- no bloquea ni deshace lo
            // ya guardado si falla, solo avisa por consola (el dato principal
            // ya está bien).
            sincronizarAcumuladoresConCorreccion($ctx, datasetCaudalSum.entityId, datasetCaudalSum.entityType, puntoSum.x, delta, function(huboError) {
                if (huboError) {
                    console.warn('[Comparativa Caudales] la corrección de caudal se guardó bien, pero no se pudieron sincronizar del todo los acumuladores de Caudal medio/Caudal fijado -- puede que tarden en reflejar el cambio.');
                }
                function terminarYCerrar(valoresForzados) {
                    // Actualiza YA el propio grafico, sin esperar a la suscripcion.
                    puntoSum.y = nuevoValorSum;
                    if (hayVolBase) { datasetCaudalSum.volumen = nuevoVolBase; }
                    // FIX: "Caudal medio" (media_proyectada) -- se pinta YA con
                    // el valor recalculado; antes se quedaba con el viejo
                    // hasta que llegaba la siguiente trama.
                    if (valoresForzados && valoresForzados.media !== null && valoresForzados.media !== undefined) {
                        (ultimoDataset || []).forEach(function(ds) {
                            if (ds.id === 'media_proyectada') {
                                var diaHoy = calcularInicioFinDiaLocal(Date.now());
                                ds.puntos.forEach(function(p) { if (p.x >= diaHoy.inicio && p.x <= diaHoy.fin) { p.y = valoresForzados.media; } });
                            }
                        });
                    }
                    dibujarGrafico($ctx, ultimoDataset);
                    pintarLeyenda($ctx, ultimasFilasLeyenda ? ultimasFilasLeyenda.map(function(f) {
                        // refresca el "Caudal actual" de cada fila con los datasets ya corregidos
                        var ds = null;
                        (ultimoDataset || []).forEach(function(d) { if (d.id === f.id) ds = d; });
                        if (!ds) return f;
                        var copia = {};
                        for (var k in f) { if (f.hasOwnProperty(k)) copia[k] = f[k]; }
                        copia.caudalActual = ds.puntos.length > 0 ? ds.puntos[ds.puntos.length - 1].y : f.caudalActual;
                        if (ds.volumen !== undefined && f.id === 'caudal_Sum') copia.volumenTotal = ds.volumen;
                        return copia;
                    }) : filasLeyendaDesdeDatasets(ultimoDataset));
                    cerrar();
                }
                // FIX: guarda el ajuste de volumen de esta corrección (ver
                // CLAVE_AJUSTE_VOLUMEN), para que el "Volumen total" del grupo
                // (suma de caudalímetros + ajustes) refleje el cambio.
                var ajustePrevio = parseFloat(ajustesVolumenHoy[puntoSum.x]) || 0;
                var ajusteNuevo = Math.round((ajustePrevio + deltaVolumenM3) * 1000) / 1000;
                ajustesVolumenHoy[puntoSum.x] = ajusteNuevo;
                borrarYGuardarTelemetria($ctx, datasetCaudalSum.entityId, datasetCaudalSum.entityType, CLAVE_AJUSTE_VOLUMEN, puntoSum.x, ajusteNuevo, function(okAjuste) {
                    if (!okAjuste) { console.warn('[Comparativa Caudales] no se pudo guardar el ajuste de volumen de la corrección.'); }
                });
                if (huboError) {
                    // Si el ajuste de acumuladores ha fallado, no tiene sentido
                    // forzar el recalculo con datos que pueden estar a medias.
                    terminarYCerrar(null);
                    return;
                }
                // Fuerza YA la reescritura de los puntos de "media_proyectada" y
                // "caudal_fijado" de hoy con el valor recalculado, para que la
                // grafica refleje el cambio al instante (ver comentario en
                // forzarRecalculoInmediato) en vez de esperar a la proxima trama.
                forzarRecalculoInmediato($ctx, datasetCaudalSum.entityId, datasetCaudalSum.entityType, function(huboErrorForzado, valoresForzados) {
                    if (huboErrorForzado) {
                        console.warn('[Comparativa Caudales] no se pudo forzar la reescritura inmediata de media_proyectada/caudal_fijado -- se actualizarán solos con la próxima trama.');
                    }
                    terminarYCerrar(valoresForzados);
                });
            });
        });
    });
}
// Reconstruye las filas de leyenda "en vivo" directamente desde los
// datasets ya actualizados en local (para refrescar los numeros de la
// leyenda al instante tras guardar, sin esperar a la suscripcion).
function filasLeyendaDesdeDatasets(datasets) {
    ultimasFilasLeyenda = datasets.map(function(ds) {
        var ultimo = ds.puntos.length > 0 ? ds.puntos[ds.puntos.length - 1].y : null;
        var nombre = SERIES_FIJAS.hasOwnProperty(ds.id) ? SERIES_FIJAS[ds.id].label : ds.label;
        return { id: ds.id, color: ds.color, nombre: nombre, caudalActual: ultimo, volumenTotal: (ds.volumen !== undefined ? ds.volumen : null) };
    });
    return ultimasFilasLeyenda;
}
self.onResize = function() {
    if (ultimoDataset) { dibujarGrafico(self.ctx, ultimoDataset); }
};
self.onDestroy = function() {};

